import { supabase } from '../config/supabase';
import { handleAuthError } from './errorHandler';
import { chatMessagesService } from './chatMessagesService';
import { QuickEntryData } from '../components/QuickEntryCard';

export interface DailyStatistic {
  id: string;
  metricType: QuickEntryData['metricType'];
  data: QuickEntryData;
  isConfirmed: boolean;
  createdAt: Date | string;
  timestamp: string;
  sourceType?: 'chat' | 'health' | 'exercise' | 'emotion';
  sourceId?: string;
}

export interface MetricTypeCount {
  metricType: QuickEntryData['metricType'];
  label: string;
  count: number;
  confirmedCount: number;
  unconfirmedCount: number;
}

export const dailyStatisticsService = {
  /**
   * 跨来源去重：chat quickEntry 与 health_records 可能同一条业务（先聊后入库或双写）
   */
  matchesQuickEntryDuplicate(a: DailyStatistic, b: DailyStatistic): boolean {
    if (a.metricType !== b.metricType) return false;
    const timeDiff = Math.abs(this.toTimestamp(a.createdAt) - this.toTimestamp(b.createdAt));
    if (timeDiff >= 5 * 60 * 1000) return false;
    const ca = a.data;
    const cb = b.data;
    switch (a.metricType) {
      case 'water':
      case 'weight':
      case 'steps':
      case 'sleep':
      case 'blood_glucose':
      case 'supplement':
        return ca.value === cb.value;
      case 'food':
        return ca.foodName === cb.foodName && ca.calories === cb.calories;
      case 'exercise':
        return ca.exerciseName === cb.exerciseName && ca.calories === cb.calories;
      case 'emotion':
        return ca.emotionType === cb.emotionType;
      case 'measurements':
        return JSON.stringify(ca.measurements ?? null) === JSON.stringify(cb.measurements ?? null);
      default:
        return false;
    }
  },

  toTimestamp(value: unknown): number {
    if (value instanceof Date) {
      const ts = value.getTime();
      return Number.isNaN(ts) ? 0 : ts;
    }
    if (typeof value === 'string' || typeof value === 'number') {
      const ts = new Date(value).getTime();
      return Number.isNaN(ts) ? 0 : ts;
    }
    return 0;
  },
  inferDataSource(
    record: {
      source?: unknown;
      notes?: unknown;
      message?: unknown;
      exercise_data?: unknown;
      nutrition_data?: unknown;
    },
    fallback?: QuickEntryData['dataSource']
  ): QuickEntryData['dataSource'] {
    const ed = record.exercise_data && typeof record.exercise_data === 'object' ? (record.exercise_data as Record<string, unknown>) : null;
    if (ed?.source === 'ai') return 'ai';
    if (ed?.source === 'manual') return 'manual';
    const nd = record.nutrition_data && typeof record.nutrition_data === 'object' ? (record.nutrition_data as Record<string, unknown>) : null;
    if (nd?.source === 'ai') return 'ai';
    if (nd?.source === 'manual') return 'manual';

    const explicitSource = typeof record.source === 'string' ? record.source.toLowerCase() : '';
    if (explicitSource === 'ai') return 'ai';
    if (explicitSource === 'manual') return 'manual';
    if (fallback === 'ai' || fallback === 'manual') return fallback;

    const text = `${typeof record.notes === 'string' ? record.notes : ''} ${typeof record.message === 'string' ? record.message : ''}`;
    const aiHints = ['AI记录', 'AI创建', 'AI识别'];
    return aiHints.some((hint) => text.includes(hint)) ? 'ai' : 'manual';
  },
  getCardIdentityKey(card: DailyStatistic): string {
    if (card.sourceType && card.sourceId) {
      return `${card.sourceType}:${card.sourceId}`;
    }
    // 兜底：尽量避免误吞真实记录，使用更细粒度字段构造 key
    const ts = this.toTimestamp(card.createdAt);
    const base = `${card.metricType}-${ts}-${card.data.value ?? ''}`;
    const secondary = `${card.data.foodName || ''}-${card.data.exerciseName || ''}-${card.data.emotionType || ''}-${card.data.notes || ''}`;
    return `${base}-${secondary}`;
  },
  /**
   * Get all quick entry cards created today
   * 从 chat_messages 和 health_records 两个数据源获取今天的记录
   */
  async getTodayQuickEntryCards(): Promise<DailyStatistic[]> {
    try {
      const { data: { user } } = await supabase.auth.getUser();
      if (!user) {
        handleAuthError(new Error('User not authenticated'));
      }

      const today = new Date();
      today.setHours(0, 0, 0, 0);
      const tomorrow = new Date(today);
      tomorrow.setDate(tomorrow.getDate() + 1);

      // 1. 从 chat_messages 获取 quickEntry 消息
      const allMessages = await chatMessagesService.getMessagesByDateRange(user.id, today, tomorrow);
      const quickEntryMessages = allMessages.filter(msg => msg.message_type === 'quickEntry');

      const chatCards: DailyStatistic[] = quickEntryMessages
        .filter(record => record.quick_entry_data)
        .map(record => {
          const quickEntryData = record.quick_entry_data as QuickEntryData;

          // Ensure the date is properly converted if it exists
          if (quickEntryData.date && typeof quickEntryData.date === 'string') {
            quickEntryData.date = new Date(quickEntryData.date);
          }

          return {
            id: record.id,
            metricType: quickEntryData.metricType,
            data: quickEntryData,
            isConfirmed: (record.is_quick_entry_confirmed || false),
            createdAt: new Date(record.created_at),
            sourceType: 'chat',
            sourceId: record.id,
            timestamp: new Date(record.created_at).toLocaleString('zh-CN', {
              hour: '2-digit',
              minute: '2-digit'
            })
          };
        });

      // 2. 从 health_records（含运动 exercise）与 emotion_records 获取今天的记录
      const chatMessageIds = new Set(quickEntryMessages.map(msg => msg.id));

      // 使用 Promise.allSettled 确保即使某个查询失败，其他查询仍能继续
      const [healthRecordsResult, emotionRecordsResult] = await Promise.allSettled([
        supabase
          .from('health_records')
          .select('*')
          .eq('user_id', user.id)
          .gte('recorded_at', today.toISOString())
          .lt('recorded_at', tomorrow.toISOString())
          .in('record_type', ['food', 'water', 'steps', 'weight', 'sleep', 'measurements', 'blood_glucose', 'supplement', 'exercise']),
        supabase
          .from('emotion_records')
          .select('*')
          .eq('user_id', user.id)
          .gte('recorded_at', today.toISOString())
          .lt('recorded_at', tomorrow.toISOString())
      ]);

      // 安全地提取数据，即使查询失败也返回空数组
      const healthRecords = (healthRecordsResult.status === 'fulfilled' && !healthRecordsResult.value.error) 
        ? healthRecordsResult.value.data || [] 
        : [];
      const emotionRecords = (emotionRecordsResult.status === 'fulfilled' && !emotionRecordsResult.value.error) 
        ? emotionRecordsResult.value.data || [] 
        : [];

      // 只在有错误时记录日志
      if (healthRecordsResult.status === 'rejected' || (healthRecordsResult.status === 'fulfilled' && healthRecordsResult.value.error)) {
        console.error('Error fetching health records:', 
          healthRecordsResult.status === 'rejected' ? healthRecordsResult.reason : healthRecordsResult.value.error);
      }
      if (emotionRecordsResult.status === 'rejected' || (emotionRecordsResult.status === 'fulfilled' && emotionRecordsResult.value.error)) {
        console.error('Error fetching emotion records:', 
          emotionRecordsResult.status === 'rejected' ? emotionRecordsResult.reason : emotionRecordsResult.value.error);
      }

      const healthCards: DailyStatistic[] = (healthRecords || [])
        .filter(record => {
          // 如果记录有 chat_message_id，且该 ID 已在 chat_messages 中存在，则跳过（避免重复）
          // 注意：如果 health_records 表中没有 chat_message_id 字段，这个检查会被忽略
          if ((record as any).chat_message_id) {
            return !chatMessageIds.has((record as any).chat_message_id);
          }
          // 统计页面只显示AI创建的卡片，排除手动添加的记录（如首页添加的体重）
          const notes = record.notes || '';
          const notesAi = notes.includes('AI记录') || notes.includes('AI创建');
          const exerciseEd = record.record_type === 'exercise' ? (record.exercise_data as { source?: string } | null) : null;
          const exerciseAi = record.record_type === 'exercise' && exerciseEd?.source === 'ai';
          const nutritionNd = record.record_type === 'food' ? (record.nutrition_data as { source?: string } | null) : null;
          const foodAi = record.record_type === 'food' && nutritionNd?.source === 'ai';
          const isAICreated = notesAi || exerciseAi || foodAi;
          return isAICreated;
        })
        .map(record => {
          // 将 health_records 转换为 QuickEntryData 格式
          const notes = record.notes || '';
          const quickEntryData: QuickEntryData = {
            metricType: record.record_type as QuickEntryData['metricType'],
            value: Number(record.value),
            unit: record.unit || undefined,
            date: new Date(record.recorded_at),
            notes: record.notes || undefined,
            isSavedToDatabase: true,
            dataSource: this.inferDataSource({
              source: (record as any).source,
              notes: record.notes,
              exercise_data: record.exercise_data,
              nutrition_data: record.nutrition_data,
            }),
            syncedToRecords: true,
          };

          // 根据不同类型填充特定字段
          switch (record.record_type) {
            case 'food':
              if (record.nutrition_data) {
                const nutrition = record.nutrition_data as any;
                quickEntryData.foodName = nutrition.name || '食物';
                quickEntryData.calories = nutrition.calories || 0;
                quickEntryData.mealType = nutrition.mealType || '加餐';
                quickEntryData.quantity = nutrition.quantity || 1;
              }
              break;
            case 'measurements':
              if (record.measurement_data) {
                const measurements = record.measurement_data as any;
                if (measurements.chest || measurements.waist || measurements.hips) {
                  quickEntryData.measurements = {
                    chest: measurements.chest,
                    waist: measurements.waist,
                    upperArm: measurements.upperArm,
                    hips: measurements.hips,
                    thigh: measurements.thigh,
                    calf: measurements.calf,
                  };
                } else {
                  quickEntryData.measurementType = measurements.type || 'other';
                }
              }
              break;
            case 'exercise': {
              const ed = (record.exercise_data as Record<string, unknown>) || {};
              const duration = Number(ed.duration) || 0;
              const calories = Number(ed.calories_burned ?? record.value) || 0;
              quickEntryData.metricType = 'exercise';
              quickEntryData.value = duration;
              quickEntryData.exerciseName = (ed.name as string) || '运动';
              quickEntryData.duration = duration;
              quickEntryData.exerciseType = (ed.exercise_type as string) || 'other';
              quickEntryData.calories = calories;
              quickEntryData.dataSource = this.inferDataSource({
                notes: record.notes,
                exercise_data: record.exercise_data,
              });
              break;
            }
            case 'emotion':
              // emotion 记录可能存储在 emotion_records 表中，这里暂时跳过
              break;
          }

          return {
            id: record.id,
            metricType: quickEntryData.metricType,
            data: quickEntryData,
            isConfirmed: true, // health_records 中的记录都是已确认的
            createdAt: new Date(record.recorded_at),
            sourceType: 'health',
            sourceId: record.id,
            timestamp: new Date(record.recorded_at).toLocaleString('zh-CN', {
              hour: '2-digit',
              minute: '2-digit'
            })
          };
        })
        .filter(card => {
          return card.metricType !== 'emotion';
        });

      // 3. 从 emotion_records 获取今天的心情记录（只显示AI创建的）
      // 🔥 排除已确认的 chat_messages 卡片对应的心情记录，避免重复
      const confirmedEmotionChatCards = chatCards.filter(
        card => card.isConfirmed && card.metricType === 'emotion'
      );
      const emotionCards: DailyStatistic[] = emotionRecords
        .filter(record => {
          // 显示所有情绪记录（AI识别 + 手动记录），确保新创建的心情能出现在待确认/已确认列表
          // 检查是否有已确认的 chat_messages 卡片匹配这条记录（避免重复）
          const hasMatchingConfirmedChatCard = confirmedEmotionChatCards.some(chatCard => {
            const recordTime = this.toTimestamp(record.recorded_at);
            const chatTime = this.toTimestamp(chatCard.createdAt);
            const timeDiff = Math.abs(recordTime - chatTime);
            const chatEmotion = (chatCard.data as any)?.emotionType || '';
            const recordEmotion = record.emotion || '';
            return chatEmotion === recordEmotion && timeDiff < 5 * 60 * 1000; // 5分钟内、情绪类型相同
          });
          return !hasMatchingConfirmedChatCard;
        })
        .map(record => {
        const quickEntryData: QuickEntryData = {
          metricType: 'emotion',
          value: record.intensity || 0.5,
          date: new Date(record.recorded_at),
          notes: record.message || undefined,
          emotionType: record.emotion,
          intensity: record.intensity,
          isSavedToDatabase: true,
          dataSource: this.inferDataSource({ source: (record as any).source, message: record.message }),
          syncedToRecords: true,
        };

        return {
          id: record.id,
          metricType: 'emotion',
          data: quickEntryData,
          isConfirmed: true,
          createdAt: new Date(record.recorded_at),
          sourceType: 'emotion',
          sourceId: record.id,
          timestamp: new Date(record.recorded_at).toLocaleString('zh-CN', {
            hour: '2-digit',
            minute: '2-digit'
          })
        };
      });

      // 4. 合并所有数据源，去重并排序
      // 🔥 修复：优先处理已确认的卡片，避免重复
      // 如果 chat_messages 中的卡片已确认，就不从 health_records 中获取相同的记录
      // 过滤 health_records：排除已确认的 chat_messages 卡片对应的记录
      // 通过比较时间戳、类型和值来判断是否是同一条记录
      // 与任意 chat quickEntry 视为同一条则去掉 health 侧，避免待确认/已确认双条（含未确认 chat）
      const filteredHealthCards = healthCards.filter(
        (healthCard) => !chatCards.some((chatCard) => this.matchesQuickEntryDuplicate(healthCard, chatCard))
      );

      const allCards = [...chatCards, ...filteredHealthCards, ...emotionCards];

      // 去重：优先按来源主键去重，兜底才用复合字段，避免“分钟+值”误吞合法记录
      const uniqueCards = new Map<string, DailyStatistic>();
      allCards.forEach(card => {
        const key = this.getCardIdentityKey(card);

        if (!uniqueCards.has(key)) {
          uniqueCards.set(key, card);
        } else {
          // 如果已存在，优先保留已确认的记录，或者保留 chat_messages 中的记录（因为它是原始来源）
          const existing = uniqueCards.get(key)!;
          if (card.isConfirmed && !existing.isConfirmed) {
            uniqueCards.set(key, card);
          } else if (card.sourceType === 'chat' && existing.sourceType !== 'chat') {
            // 优先保留 chat_messages 中的记录
            uniqueCards.set(key, card);
          }
        }
      });

      // 按时间降序排序
      const sortedCards = Array.from(uniqueCards.values())
        .sort((a, b) => this.toTimestamp(b.createdAt) - this.toTimestamp(a.createdAt));

      return sortedCards;
    } catch (error) {
      console.error('Error in getTodayQuickEntryCards:', error);
      return [];
    }
  },

  /**
   * Get summary statistics by metric type
   */
  async getTodayStatisticsSummary(): Promise<{
    totalCards: number;
    confirmedCards: number;
    unconfirmedCards: number;
    metricTypeCounts: MetricTypeCount[];
    totalCalories: number;
    totalCaloriesIn: number;
    totalCaloriesOut: number;
  }> {
    const cards = await this.getTodayQuickEntryCards();

    const totalCards = cards.length;
    const confirmedCards = cards.filter(card => card.isConfirmed).length;
    const unconfirmedCards = cards.filter(card => !card.isConfirmed).length;

    // Group by metric type
    const metricTypeMap = new Map<string, { confirmed: number; unconfirmed: number }>();

    cards.forEach(card => {
      const key = card.metricType;
      const existing = metricTypeMap.get(key) || { confirmed: 0, unconfirmed: 0 };

      if (card.isConfirmed) {
        existing.confirmed++;
      } else {
        existing.unconfirmed++;
      }

      metricTypeMap.set(key, existing);
    });

    const metricTypeCounts: MetricTypeCount[] = Array.from(metricTypeMap.entries()).map(([metricType, counts]) => ({
      metricType: metricType as QuickEntryData['metricType'],
      label: this.getMetricTypeLabel(metricType as QuickEntryData['metricType']),
      count: counts.confirmed + counts.unconfirmed,
      confirmedCount: counts.confirmed,
      unconfirmedCount: counts.unconfirmed
    }));

    // Calculate total calories
    let totalCaloriesIn = 0;
    let totalCaloriesOut = 0;

    cards.forEach(card => {
      if (card.isConfirmed && card.data.calories) {
        if (card.metricType === 'food') {
          totalCaloriesIn += card.data.calories;
        } else if (card.metricType === 'exercise') {
          totalCaloriesOut += card.data.calories;
        }
      }
    });

    const totalCalories = totalCaloriesIn - totalCaloriesOut;

    return {
      totalCards,
      confirmedCards,
      unconfirmedCards,
      metricTypeCounts,
      totalCalories,
      totalCaloriesIn,
      totalCaloriesOut
    };
  },

  /**
   * Get label for metric type
   */
  getMetricTypeLabel(metricType: QuickEntryData['metricType']): string {
    const labels: Record<QuickEntryData['metricType'], string> = {
      food: '饮食',
      water: '喝水',
      exercise: '运动',
      steps: '步数',
      weight: '体重',
      sleep: '睡眠',
      measurements: '围度',
      emotion: '心情',
      blood_glucose: '血糖',
      supplement: '补剂'
    };

    return labels[metricType] || '记录';
  },

  /**
   * Get cards filtered by confirmation status
   */
  async getFilteredCards(filter: 'all' | 'confirmed' | 'unconfirmed'): Promise<DailyStatistic[]> {
    const allCards = await this.getTodayQuickEntryCards();

    if (filter === 'all') {
      return allCards;
    } else if (filter === 'confirmed') {
      return allCards.filter(card => card.isConfirmed);
    } else {
      return allCards.filter(card => !card.isConfirmed);
    }
  },

  /**
   * Update quick entry card data
   */
  async updateQuickEntryCard(cardId: string, updatedData: QuickEntryData): Promise<void> {
    try {
      // 优先通过统一的聊天服务更新确认状态与数据
      const { data: { user } } = await supabase.auth.getUser();
      if (!user) {
        handleAuthError(new Error('User not authenticated'));
      }

      await chatMessagesService.updateMessage(cardId, {
        is_quick_entry_confirmed: true,
        quick_entry_data: updatedData,
      });

      // 如果数据已保存到数据库（isSavedToDatabase为true），则同步更新health_records
      if (updatedData.isSavedToDatabase) {
        // 直接使用 Supabase 查询健康记录
        const { data: records, error } = await supabase
          .from('health_records')
          .select('*')
          .eq('user_id', user.id)
          .eq('record_type', updatedData.metricType)
          .eq('chat_message_id', cardId);

        if (error) {
          console.error('Error fetching health records:', error);
          return;
        }

        if (records && records.length > 0) {
          // 更新对应的health_record
          const recordId = records[0].id;

          // 根据metricType准备更新数据
          const updateData: any = {
            recorded_at: updatedData.date ? new Date(updatedData.date).toISOString() : new Date().toISOString(),
            notes: updatedData.notes || null
          };

          // 根据不同类型添加特定字段
          switch (updatedData.metricType) {
            case 'food':
              // food 类型的数据通过 nutrition_data 存储，需要从现有记录中获取或构建
              // 如果记录中已有 nutrition_data，保留它；否则根据 QuickEntryData 构建
              const existingRecord = records[0];
              if (existingRecord.nutrition_data) {
                updateData.nutrition_data = existingRecord.nutrition_data;
              } else {
                // 构建 nutrition_data
                updateData.nutrition_data = {
                  name: updatedData.foodName || '食物',
                  calories: updatedData.calories || 0,
                  mealType: updatedData.mealType || '加餐',
                  quantity: updatedData.quantity || 1,
                };
              }
              break;
            case 'water':
              updateData.value = updatedData.value;
              break;
            case 'exercise':
              updateData.exercise_name = updatedData.exerciseName;
              updateData.duration = updatedData.duration;
              updateData.calories_burned = updatedData.calories;
              updateData.exercise_type = updatedData.exerciseType;
              break;
            case 'weight':
              updateData.value = updatedData.value;
              break;
            case 'sleep':
              updateData.duration = updatedData.value;
              break;
            case 'blood_glucose':
              updateData.value = updatedData.value;
              // measurement_time 字段可能不存在于 QuickEntryData，使用 recorded_at 作为替代
              // 如果需要，可以从现有记录中获取
              if (records[0].measurement_time) {
                updateData.measurement_time = records[0].measurement_time;
              }
              break;
            case 'emotion':
              updateData.emotion_type = updatedData.emotionType;
              updateData.intensity = updatedData.intensity;
              break;
            case 'supplement':
              updateData.supplement_name = updatedData.supplementName;
              updateData.dosage = updatedData.dosage;
              updateData.unit = updatedData.unit;
              break;
          }

          // 直接使用 Supabase 更新数据
          try {
            const { error: updateError } = await supabase
              .from('health_records')
              .update(updateData)
              .eq('id', recordId);

            if (updateError) {
              console.error('Error updating health record:', updateError);
            }
          } catch (error) {
            console.error('Error updating health record:', error);
          }
        }
      }
    } catch (error) {
      console.error('Error in updateQuickEntryCard:', error);
      throw error;
    }
  },

  /**
   * 统一删除「今日数据统计 / 日反馈待确认 / 聊天快捷卡片」中的同一条目。
   * - 来源为 chat：必须先删 health_records（chat_message_id = 消息 id），再删 chat_messages；
   *   若先删消息，FK ON DELETE SET NULL 会清空关联，导致无法再用 chat_message_id 找到健康记录（孤儿数据）。
   * - 来源为 health：按 health_records.id 删除。
   * - 来源为 emotion：按 emotion_records.id 删除。
   */
  async removeQuickEntryDailyStatistic(card: DailyStatistic): Promise<void> {
    const { data: { user } } = await supabase.auth.getUser();
    if (!user) {
      handleAuthError(new Error('User not authenticated'));
    }

    if (card.sourceType === 'health') {
      const { error } = await supabase.from('health_records').delete().eq('id', card.id).eq('user_id', user.id);
      if (error) throw error;
      return;
    }

    if (card.sourceType === 'emotion') {
      const { error } = await supabase.from('emotion_records').delete().eq('id', card.id).eq('user_id', user.id);
      if (error) throw error;
      return;
    }

    // chat（及未标 sourceType 的兜底）：消息 id = card.id
    const messageId = card.id;
    const metricTypes = [
      'food',
      'water',
      'exercise',
      'steps',
      'weight',
      'sleep',
      'measurements',
      'blood_glucose',
      'supplement',
    ] as const;

    for (const type of metricTypes) {
      const { data: records, error: queryError } = await supabase
        .from('health_records')
        .select('id')
        .eq('user_id', user.id)
        .eq('record_type', type)
        .eq('chat_message_id', messageId);

      if (queryError) {
        console.error(`Error querying health records for ${type}:`, queryError);
        continue;
      }
      if (records?.length) {
        const recordIds = records.map((r) => r.id);
        const { error: deleteError } = await supabase.from('health_records').delete().in('id', recordIds);
        if (deleteError) {
          console.error(`Error deleting health records for ${type}:`, deleteError);
        }
      }
    }

    await chatMessagesService.deleteMessage(messageId);
  },

  /**
   * @deprecated 请使用 removeQuickEntryDailyStatistic(card)；保留兼容仅传消息 id 的旧调用。
   */
  async deleteQuickEntryCard(cardId: string, metricType?: QuickEntryData['metricType']): Promise<void> {
    await this.removeQuickEntryDailyStatistic({
      id: cardId,
      metricType: metricType || 'food',
      data: { metricType: metricType || 'food', value: 0 },
      isConfirmed: false,
      createdAt: new Date(),
      sourceType: 'chat',
      sourceId: cardId,
      timestamp: '',
    });
  },
};

