  };
  exercise: {
    records: any[];
    totalCalories: number;
    totalDuration: number;
  };
  measurements: {
    record: HealthRecord | null;
    chest: number | null;
    waist: number | null;
    upperArm: number | null;
    hips: number | null;
    thigh: number | null;
