/**
 * Calculate nutrition totals from food records
 */
function calculateNutritionTotals(foodRecords: any[]): { carbs: number; protein: number; fat: number } {
  const totals = { carbs: 0, protein: 0, fat: 0 };

  foodRecords.forEach(record => {
    if (record.nutrition_data) {
      totals.carbs += record.nutrition_data.carbs || 0;
      totals.protein += record.nutrition_data.protein || 0;
      totals.fat += record.nutrition_data.fat || 0;
    }
  });

  return {
    carbs: Math.round(totals.carbs),
    protein: Math.round(totals.protein),
    fat: Math.round(totals.fat),
  };
}

/**
 * Convert health records to dashboard records format
 */
function convertHealthRecordsToDashboardRecords(healthData: DayHealthData): Array<any> {
  const records: Array<any> = [];

  // Add food records
  healthData.food.records.forEach(record => {
    if (record.nutrition_data) {
      records.push({
        id: record.id,
        type: 'food' as const,
        name: record.nutrition_data.name || 'Unknown Food',
        calories: record.value,
        time: new Date(record.recorded_at).toTimeString().slice(0, 5),
        nutrition_data: record.nutrition_data,
      });
    }
  });

  // Add exercise records（health_records 行或 ExerciseRecord 扁平结构）
  healthData.exercise.records.forEach((record: any) => {
    const ed =
      record.exercise_data && typeof record.exercise_data === 'object'
        ? record.exercise_data
        : {
            name: record.exercise_name,
            exercise_type: record.exercise_type,
            duration: record.duration,
            calories_burned: record.calories_burned,
            intensity: record.intensity,
            source: record.source,
          };
    const name = ed.name || record.exercise_name;
    if (!name && !record.exercise_name) return;
    const calories = Number(record.value ?? ed.calories_burned ?? record.calories_burned ?? 0);
    records.push({
      id: record.id,
      type: 'exercise' as const,
      name: (name as string) || '运动',
      calories,
      time: new Date(record.recorded_at).toTimeString().slice(0, 5),
      exercise_data: { ...ed, name: (name as string) || '运动' },
    });
  });

  // Add water records
  healthData.water.records.forEach(record => {
    records.push({
      id: record.id,
      type: 'water' as const,
      name: `${record.value}ml`,
      time: new Date(record.recorded_at).toTimeString().slice(0, 5),
    });
  });

  // Sort by time
  records.sort((a, b) => a.time.localeCompare(b.time));

  return records;
}

/**
 * Extract time from sleep data
 */
function extractTimeFromSleepData(sleepRecord: any, field: 'bedTime' | 'wakeTime'): string {
  if (!sleepRecord || !sleepRecord.notes) return '--:--';

  try {
    const sleepData = JSON.parse(sleepRecord.notes);
    return sleepData[field] || '--:--';
  } catch {
    return '--:--';
  }
}

/**
 * Convert DayHealthData from database to DayData format for dashboard
 */
function convertHealthDataToDayData(healthData: DayHealthData, targetWeight: number, userProfile: UserProfile | null = null): DayData {
  // Calculate nutrition totals from food records
  const nutritionTotals = calculateNutritionTotals(healthData.food.records);

  // Generate hourly data for steps
  const hourlySteps = healthData.steps.hourlyData.length > 0
    ? healthData.steps.hourlyData
    : new Array(24).fill(0);

  // Convert health records to dashboard records format
  const records = convertHealthRecordsToDashboardRecords(healthData);

  // 与营养详情一致：仅订单/定制食谱同步（nutrition_data.syncId）可点亮早/午/晚；手动与 AI 不占用这三档
  const mealTypeToKey: Record<string, 'breakfast' | 'lunch' | 'dinner'> = {
    早餐: 'breakfast',
    午餐: 'lunch',
    晚餐: 'dinner',
    breakfast: 'breakfast',
    lunch: 'lunch',
    dinner: 'dinner',
  };
  const mealIntakeStatus: DayData['mealIntakeStatus'] = {};
  healthData.food.records.forEach((r) => {
    const nd = r.nutrition_data;
    if (!isOrderSyncedFoodNutrition(nd)) return;
    const mt = nd?.mealType;
    const key = mt != null ? mealTypeToKey[String(mt)] : undefined;
    if (key && !mealIntakeStatus[key]) {
      mealIntakeStatus[key] = { intakeCompletedAt: r.recorded_at };
    }
  });

  // Calculate BMR and calorie targets (simplified for now)
  const BMR = 1500; // This should come from user profile
  const targetCalories = BMR + 200; // Adjust based on user goals

  // Use profile water_intake if available, otherwise default to 2000ml
  const waterTarget = userProfile?.water_intake || 2000;
  console.log('[DashboardDataService] Water target from profile:', userProfile?.water_intake, 'using:', waterTarget);

  // Use profile sleep_hours if available for target display
  const sleepTargetHours = userProfile?.sleep_hours || 0;
  console.log('[DashboardDataService] Sleep target from profile:', userProfile?.sleep_hours, 'using:', sleepTargetHours);

  // If no sleep record but profile has sleep_hours, show target as duration
  const sleepDuration = (healthData.sleep.duration ?? 0) > 0 ? healthData.sleep.duration : sleepTargetHours;
  const hasSleepData = healthData.sleep.record !== null || sleepTargetHours > 0;

  return {
    calories: {
      remaining: targetCalories - healthData.food.totalCalories + healthData.exercise.totalCalories,
      total: targetCalories,
      foodIntake: healthData.food.totalCalories,
      exerciseBurned: healthData.exercise.totalCalories,
    },
    weight: {
      current: healthData.weight.latest,
      target: targetWeight,
      hasRecord: healthData.weight.hasRecord,
    },
    nutrition: {
      carbs: {
        current: nutritionTotals.carbs,
        target: 178,
      },
      protein: {
        current: nutritionTotals.protein,
        target: 120,
      },
      fat: {
        current: nutritionTotals.fat,
        target: 73,
      },
    },
    water: {
      current: healthData.water.total,
      target: waterTarget,
    },
    steps: {
      current: healthData.steps.total,
      target: 8000,
      hourlyData: hourlySteps,
      // 爬楼层数：当前 health_records 步数未存该字段；设备同步前固定 0，避免伪造数据
      floors: 0,
    },
    exercise: {
      calories: healthData.exercise.totalCalories,
      minutes: healthData.exercise.totalDuration,
    },
    measurements: {
      chest: healthData.measurements.chest,
      waist: healthData.measurements.waist,
      upperArm: healthData.measurements.upperArm,
      hips: healthData.measurements.hips,
      thigh: healthData.measurements.thigh,
      calf: healthData.measurements.calf,
    },
    emotion: {
      current: healthData.emotion.latest?.emotion || 'neutral',
      intensity: healthData.emotion.latest?.intensity || 0.5,
      hasRecord: healthData.emotion.records.length > 0,
    },
    sleep: {
      duration: sleepDuration ?? 0,
      quality: healthData.sleep.quality || 0,
      bedTime: extractTimeFromSleepData(healthData.sleep.record, 'bedTime'),
      wakeTime: extractTimeFromSleepData(healthData.sleep.record, 'wakeTime'),
      hasRecord: hasSleepData,
    },
    bloodGlucose: {
      current: healthData.bloodGlucose.values.length > 0
        ? healthData.bloodGlucose.values[healthData.bloodGlucose.values.length - 1].value
        : null,
      target: { min: 70, max: 100 },
      hasRecord: healthData.bloodGlucose.records.length > 0,
      lastMeasurement: healthData.bloodGlucose.values.length > 0
        ? healthData.bloodGlucose.values[healthData.bloodGlucose.values.length - 1].time
        : '--:--',
    },
    records,
    mealIntakeStatus: Object.keys(mealIntakeStatus).length > 0 ? mealIntakeStatus : undefined,
  };
}

export const dashboardDataService = {
  /**
   * Get complete health data for a specific day
   * 聚合各个独立Service的数据，符合3层架构：组件 → Hook → dashboardDataService → 各Service → Supabase
   */
  async getDayHealthData(date: Date): Promise<DayHealthData> {
    const userId = await getUserId();
    if (!userId) {
      return getEmptyDayData(date);
    }

    const startOfDay = new Date(date);
    startOfDay.setHours(0, 0, 0, 0);

    const endOfDay = new Date(date);
    endOfDay.setHours(23, 59, 59, 999);

    const { start: foodBeijingStart, end: foodBeijingEnd } = getBeijingDayBoundsForInstant(date);

    try {
      // 并行调用各个独立的Service获取数据
      const [
        weightRecords,
        waterRecords,
        stepsRecords,
        foodRecords,
        measurementRecords,
        sleepRecords,
        bloodGlucoseRecords,
        exerciseRecords,
        emotionRecords,
      ] = await Promise.all([
        weightService.getRecords(userId, startOfDay, endOfDay),
        waterService.getRecords(userId, startOfDay, endOfDay),
        stepsService.getRecords(userId, startOfDay, endOfDay),
        foodService.getRecords(userId, foodBeijingStart, foodBeijingEnd),
        measurementsService.getRecords(userId, startOfDay, endOfDay),
        sleepService.getRecords(userId, startOfDay, endOfDay),
        bloodGlucoseService.getRecords(userId, startOfDay, endOfDay),
        exerciseService.getExercisesByDateRange(startOfDay.toISOString(), endOfDay.toISOString()),
        emotionService.getEmotionRecords(userId, startOfDay, endOfDay),
      ]);

      // Process weight data
      const latestWeight = weightRecords.length > 0
        ? weightRecords[weightRecords.length - 1].value
        : null;

      // Process water data
      const totalWater = waterRecords.reduce((sum, record) => {
        const value = Number(record.value) || 0;
        return sum + value;
      }, 0);

      // Process steps data
      const totalSteps = stepsRecords.reduce((sum, record) => sum + record.value, 0);
      const hourlySteps = generateHourlyStepsData(stepsRecords as HealthRecord[]);

      // Process food data
      const totalFoodCalories = foodRecords.reduce((sum, record) => {
        const calories = record.nutrition_data?.calories || record.value || 0;
        return sum + calories;
      }, 0);

      // Process exercise data
      const totalExerciseCalories = exerciseRecords.reduce(
        (sum, record) => sum + (record.calories_burned || 0),
        0
      );
      const totalExerciseDuration = exerciseRecords.reduce(
        (sum, record) => sum + (record.duration || 0),
        0
      );

      // Process measurement data
      const latestMeasurement = measurementRecords.length > 0
        ? measurementRecords[measurementRecords.length - 1]
        : null;
      const measurementData = latestMeasurement?.measurement_data || {};

      // Process sleep data
      const latestSleep = sleepRecords.length > 0
        ? sleepRecords[sleepRecords.length - 1]
        : null;
      let sleepData = {};
      if (latestSleep?.notes) {
        try {
          // Try to parse as JSON, if it fails, treat as plain text
          sleepData = JSON.parse(latestSleep.notes);
        } catch {
          // If notes is not valid JSON (e.g., plain text like "手动记录"), use empty object
          sleepData = {};
        }
      }

      // Process blood glucose data
      const glucoseValues = bloodGlucoseRecords.map(record => ({
        time: new Date(record.recorded_at).toTimeString().slice(0, 5),
        value: record.value,
      }));

      // Process emotion data
      const latestEmotion = emotionRecords.length > 0
        ? emotionRecords[emotionRecords.length - 1]
        : null;

      return {
        date,
        weight: {
          records: weightRecords as HealthRecord[],
          latest: latestWeight,
          hasRecord: weightRecords.length > 0,
        },
        water: {
          records: waterRecords as HealthRecord[],
          total: Math.round(totalWater),
        },
        steps: {
          records: stepsRecords as HealthRecord[],
          total: Math.round(totalSteps),
          hourlyData: hourlySteps,
        },
        food: {
          records: foodRecords as HealthRecord[],
          totalCalories: Math.round(totalFoodCalories),
        },
        exercise: {
          records: exerciseRecords,
          totalCalories: Math.round(totalExerciseCalories),
          totalDuration: Math.round(totalExerciseDuration),
        },
        measurements: {
          record: latestMeasurement as HealthRecord | null,
          chest: measurementData.chest || null,
          waist: measurementData.waist || null,
          upperArm: measurementData.upperArm || null,
          hips: measurementData.hips || null,
          thigh: measurementData.thigh || null,
          calf: measurementData.calf || null,
        },
        sleep: {
          record: latestSleep as HealthRecord | null,
          duration: sleepData.duration || null,
          quality: sleepData.quality || null,
        },
        bloodGlucose: {
          records: bloodGlucoseRecords as HealthRecord[],
          values: glucoseValues,
        },
        emotion: {
          records: emotionRecords,
          latest: latestEmotion,
        },
      };
    } catch (error) {
      console.error('[DashboardDataService] Error in getDayHealthData:', error);
      return getEmptyDayData(date);
    }
  },

  /**
   * Get dashboard data for a specific date
   * 统一使用 React Query 管理缓存，不再使用 localStorage
   * This intelligently decides whether to show real data, empty data, or tutorial data
   */
  async getDayData(date: Date, options: DashboardDataOptions = {}): Promise<DayData> {
    const { showTutorialData = false, targetWeight = 60.0, userProfile = null } = options;

    // If in tutorial mode, always return mock data
    if (showTutorialData) {
      console.log('[DashboardDataService] Tutorial mode enabled, returning mock data');
      return generateMockData(date);
    }

    // Check if user is authenticated
    const { data: { user } } = await supabase.auth.getUser();

    if (!user) {
      // Anonymous users see tutorial data
      console.log('[DashboardDataService] Anonymous user, returning tutorial data');
      return generateMockData(date);
    }

    // 直接从数据库获取数据，缓存由 React Query 管理
    console.log('[DashboardDataService] Fetching real user data for:', user.id);
    const healthData = await dashboardDataService.getDayHealthData(date);
    const dayData = convertHealthDataToDayData(healthData, targetWeight, userProfile);

    return dayData;
  },

  /**
   * Check if user has any health data
   * 直接使用 Supabase 查询，符合 3 层架构规范
   */
  async hasAnyHealthData(): Promise<boolean> {
    const userId = await getUserId();
    if (!userId) return false;

    try {
      // 检查是否有任意类型的健康记录（只查询一条即可）
      const { data, error } = await supabase
        .from('health_records')
        .select('id')
        .eq('user_id', userId)
        .limit(1)
        .maybeSingle();

      if (error && error.code !== 'PGRST116') {
        // PGRST116 means no rows found, which is fine
        throw error;
      }

      return !!data;
    } catch (error) {
      console.error('[DashboardDataService] Error in hasAnyHealthData:', error);
      return false;
    }
  },

  /**
   * Check if user should see tutorial data
   * - New users who just registered
   * - Users who haven't completed onboarding
   */
  async shouldShowTutorialData(): Promise<boolean> {
    const { data: { user } } = await supabase.auth.getUser();

    if (!user) {
      return true; // Anonymous users see tutorial
    }

    // Check if user has completed onboarding
    const { data: profile } = await supabase
      .from('user_profiles')
      .select('onboarding_completed, has_seen_onboarding')
      .eq('user_id', user.id)
      .maybeSingle();

    // Show tutorial if user hasn't seen onboarding yet
    if (!profile || !profile.has_seen_onboarding) {
      return true;
    }

    // Check if user has any health data
    const hasData = await dashboardDataService.hasAnyHealthData();

    // Don't show tutorial if user has data
    return !hasData;
  },
};

import { supabase } from '../config/supabase';
import { toLocalDateString } from '../utils/dateUtils';
import { DELIVERY_MEAL_TIME_RANGES } from '../constants/deliveryMealTimes';

export interface DeliverySchedule {
  id: string;
  user_id: string;
  delivery_date: string; // YYYY-MM-DD
  meal_type: 'breakfast' | 'lunch' | 'dinner';
  delivery_time_start?: string; // HH:MM
  delivery_time_end?: string; // HH:MM
  status: 'pending' | 'scheduled' | 'preparing' | 'shipped' | 'delivered' | 'cancelled';
  delivery_address_id?: string;
  is_locked?: boolean;
  locked_at?: string | null;
  created_at?: string;
  updated_at?: string;
}

export interface DeliveryScheduleUpsertInput {
  date: Date | string;
  mealType: 'breakfast' | 'lunch' | 'dinner' | string;
  addressId: string;
  isLocked?: boolean;
}

const normalizeDateString = (date: Date | string): string => {
  if (typeof date === 'string') return date.split('T')[0];
  return toLocalDateString(date);
};

/**
 * 配送计划服务
 * 用于获取用户的配送计划数据
 */
export const deliveryScheduleService = {
  async logAuditEvent(payload: {
    user_id?: string | null;
    action: string;
    entity_type: 'delivery_schedule' | string;
    entity_id?: string | null;
    before_data?: any;
    after_data?: any;
    reason?: string;
    source?: string;
  }) {
    try {
      if (!payload.user_id) return;
      await supabase.from('delivery_audit_logs').insert({
        user_id: payload.user_id,
        action: payload.action,
        entity_type: payload.entity_type,
        entity_id: payload.entity_id || null,
        before_data: payload.before_data || null,
        after_data: payload.after_data || null,
        reason: payload.reason || null,
        source: payload.source || 'app',
      });
    } catch (error) {
      console.warn('⚠️ Failed to write delivery_audit_logs for schedules:', error);
    }
  },

  /**
   * 获取用户的配送计划
   * @param userId 用户ID
   * @param startDate 开始日期（可选）
   * @param endDate 结束日期（可选）
   * @returns 配送计划数组
   */
  async getUserDeliverySchedules(
    userId: string,
    startDate?: Date,
    endDate?: Date
  ): Promise<DeliverySchedule[]> {
    try {
      let query = supabase
        .from('delivery_schedules')
        .select('*')
        .eq('user_id', userId)
        .eq('delivery_type', 'meal')
        .not('meal_type', 'is', null)
        .order('delivery_date', { ascending: true })
        .order('meal_type', { ascending: true });

      // 如果有开始日期，添加过滤条件（使用本地日期，避免 UTC 时区错位）
      if (startDate) {
        const startDateStr = toLocalDateString(startDate);
        query = query.gte('delivery_date', startDateStr);
      }

      // 如果有结束日期，添加过滤条件
      if (endDate) {
        const endDateStr = toLocalDateString(endDate);
        query = query.lte('delivery_date', endDateStr);
      }

      const { data, error } = await query;

      if (error) {
        console.error('Error fetching delivery schedules:', error);
        throw error;
      }

      return (data || []) as DeliverySchedule[];
    } catch (error) {
      console.error('Error in getUserDeliverySchedules:', error);
      return [];
    }
  },

  /**
   * 获取指定日期的配送计划
   * @param userId 用户ID
   * @param date 日期
   * @returns 该日期的配送计划数组
   */
  async getDeliverySchedulesByDate(
    userId: string,
    date: Date | string
  ): Promise<DeliverySchedule[]> {
    try {
      const dateStr = typeof date === 'string' ? date : toLocalDateString(date);

      const { data, error } = await supabase
        .from('delivery_schedules')
        .select('*')
        .eq('user_id', userId)
        .eq('delivery_type', 'meal')
        .eq('delivery_date', dateStr)
        .order('meal_type', { ascending: true });

      if (error) {
        console.error('Error fetching delivery schedules by date:', error);
        throw error;
      }

      return (data || []) as DeliverySchedule[];
    } catch (error) {
      console.error('Error in getDeliverySchedulesByDate:', error);
      return [];
    }
  },

  /**
   * 获取配送计划的最早和最晚日期
   * @param userId 用户ID
   * @returns 包含最早和最晚日期的对象
   */
  async getDeliveryDateRange(userId: string): Promise<{
    startDate: Date | null;
    endDate: Date | null;
  }> {
    try {
      console.log('🔍 [deliveryScheduleService] Getting delivery date range for user:', userId);

      // 获取最早的配送日期
      const { data: earliest, error: earliestError } = await supabase
        .from('delivery_schedules')
        .select('delivery_date')
        .eq('user_id', userId)
        .eq('delivery_type', 'meal')
        .not('meal_type', 'is', null)
        .order('delivery_date', { ascending: true })
        .limit(1)
        .maybeSingle();

      // 获取最晚的配送日期
      const { data: latest, error: latestError } = await supabase
        .from('delivery_schedules')
        .select('delivery_date')
        .eq('user_id', userId)
        .eq('delivery_type', 'meal')
        .not('meal_type', 'is', null)
        .order('delivery_date', { ascending: false })
        .limit(1)
        .maybeSingle();

      if (earliestError && earliestError.code !== 'PGRST116') {
        console.error('❌ [deliveryScheduleService] Error fetching earliest delivery date:', earliestError);
      }

      if (latestError && latestError.code !== 'PGRST116') {
        console.error('❌ [deliveryScheduleService] Error fetching latest delivery date:', latestError);
      }

      // 🔥 修复：正确解析日期字符串，避免时区问题
      let startDate: Date | null = null;
      let endDate: Date | null = null;

      if (earliest?.delivery_date) {
        // delivery_date 格式是 YYYY-MM-DD，需要解析为本地日期（不包含时间）
        const [year, month, day] = earliest.delivery_date.split('-').map(Number);
        startDate = new Date(year, month - 1, day);
        startDate.setHours(0, 0, 0, 0);
        console.log('✅ [deliveryScheduleService] Earliest date:', {
          raw: earliest.delivery_date,
          parsed: toLocalDateString(startDate),
          local: `${startDate.getFullYear()}-${String(startDate.getMonth() + 1).padStart(2, '0')}-${String(startDate.getDate()).padStart(2, '0')}`
        });
      }

      if (latest?.delivery_date) {
        // delivery_date 格式是 YYYY-MM-DD，需要解析为本地日期（不包含时间）
        const [year, month, day] = latest.delivery_date.split('-').map(Number);
        endDate = new Date(year, month - 1, day);
        endDate.setHours(0, 0, 0, 0);
        console.log('✅ [deliveryScheduleService] Latest date:', {
          raw: latest.delivery_date,
          parsed: toLocalDateString(endDate),
          local: `${endDate.getFullYear()}-${String(endDate.getMonth() + 1).padStart(2, '0')}-${String(endDate.getDate()).padStart(2, '0')}`
        });
      }

      return {
        startDate,
        endDate,
      };
    } catch (error) {
      console.error('❌ [deliveryScheduleService] Error in getDeliveryDateRange:', error);
      return {
        startDate: null,
        endDate: null,
      };
    }
  },

  async syncUserDeliverySchedules(
    userId: string,
    items: DeliveryScheduleUpsertInput[],
    orderId?: string | null
  ): Promise<{
    targetCount: number;
    insertedCount: number;
    updatedCount: number;
    invalidAddressCount: number;
    errorCount: number;
    hasErrors: boolean;
  }> {
    try {
      if (!userId || !items.length) {
        return {
          targetCount: 0,
          insertedCount: 0,
          updatedCount: 0,
          invalidAddressCount: 0,
          errorCount: 0,
          hasErrors: false,
        };
      }

      // 去重：同一天同餐次仅保留最后一次修改
      const deduped = new Map<string, DeliveryScheduleUpsertInput>();
      items.forEach((item) => {
        if (!item?.addressId) return;
        const dateStr = normalizeDateString(item.date);
        const key = `${dateStr}-${item.mealType}`;
        deduped.set(key, { ...item, date: dateStr });
      });
      const normalizedItems = Array.from(deduped.values());
      if (!normalizedItems.length) {
        return {
          targetCount: 0,
          insertedCount: 0,
          updatedCount: 0,
          invalidAddressCount: 0,
          errorCount: 0,
          hasErrors: false,
        };
      }

      const targetCount = normalizedItems.length;
      let errorCount = 0;
      let hasErrors = false;

      const dateStrings = Array.from(new Set(normalizedItems.map(i => String(i.date))));
      const mealTypes = Array.from(new Set(normalizedItems.map(i => i.mealType)));

      // 地址必须属于当前用户且未删除（与统一配送计划直连写入规则一致）
      const addressIds = [...new Set(normalizedItems.map((i) => i.addressId).filter(Boolean))];
      let validAddressIdSet = new Set<string>();
      if (addressIds.length > 0) {
        const { data: validAddrs, error: addressErr } = await supabase
          .from('delivery_addresses')
          .select('id')
          .eq('user_id', userId)
          .eq('is_deleted', false)
          .in('id', addressIds);
        if (addressErr) {
          console.error('❌ [deliveryScheduleService] Failed to validate address ownership:', addressErr);
          return {
            targetCount,
            insertedCount: 0,
            updatedCount: 0,
            invalidAddressCount: addressIds.length,
            errorCount: 1,
            hasErrors: true,
          };
        }
        validAddressIdSet = new Set((validAddrs || []).map((a: any) => a.id));
      }

      const validItems = normalizedItems.filter((item) => validAddressIdSet.has(item.addressId));
      const invalidAddressCount = targetCount - validItems.length;
      if (invalidAddressCount > 0) {
        hasErrors = true;
        errorCount += 1;
        console.warn('⚠️ [deliveryScheduleService] Filtered invalid/unauthorized address items:', {
          targetCount,
          validCount: validItems.length,
          invalidAddressCount,
        });
      }
      if (validItems.length === 0) {
        return {
          targetCount,
          insertedCount: 0,
          updatedCount: 0,
          invalidAddressCount,
          errorCount,
          hasErrors,
        };
      }

      // 批量拉取本次涉及的地址快照，确保地址修改后快照也同步更新
      const addrIdsToFetch = [...new Set(validItems.map((i) => i.addressId).filter(Boolean))];
      const addrSnapshotMap: Record<string, { address: string; label: string; contact_name: string; phone: string }> = {};
      if (addrIdsToFetch.length > 0) {
        const { data: addrs } = await supabase
          .from('delivery_addresses')
          .select('id, address, door_number, label, contact_name, phone')
          .in('id', addrIdsToFetch)
          .eq('is_deleted', false);
        (addrs || []).forEach((a: any) => {
          addrSnapshotMap[a.id] = {
            address: [a.address, a.door_number].filter(Boolean).join(' ').trim(),
            label: a.label || a.tag || '',
            contact_name: a.contact_name || '',
            phone: a.phone || '',
          };
        });
      }

      const { data: existingRows, error: fetchError } = await supabase
        .from('delivery_schedules')
        .select('id, user_id, delivery_date, meal_type, delivery_address_id, is_locked, locked_at, status, order_id, updated_at')
        .eq('user_id', userId)
        .eq('delivery_type', 'meal')
        .in('delivery_date', dateStrings)
        .in('meal_type', mealTypes);

      if (fetchError) {
        console.error('❌ [deliveryScheduleService] Failed to fetch existing schedules:', fetchError);
        return {
          targetCount,
          insertedCount: 0,
          updatedCount: 0,
          invalidAddressCount,
          errorCount: errorCount + 1,
          hasErrors: true,
        };
      }

      const existingByKey = new Map<string, any>();
      (existingRows || []).forEach((row: any) => {
        existingByKey.set(`${row.delivery_date}-${row.meal_type}`, row);
      });

      const inserts: Record<string, any>[] = [];
      const updates: {
        id: string;
        payload: Record<string, any>;
        before: any;
        expectedUpdatedAt?: string | null;
        needOrderSnapshot?: string | null;
      }[] = [];

      validItems.forEach((item) => {
        const dateStr = String(item.date);
        const key = `${dateStr}-${item.mealType}`;
        const existing = existingByKey.get(key);
        const timeRange = DELIVERY_MEAL_TIME_RANGES[item.mealType as keyof typeof DELIVERY_MEAL_TIME_RANGES] || DELIVERY_MEAL_TIME_RANGES.lunch;
        const desiredLocked = typeof item.isLocked === 'boolean' ? item.isLocked : true;
        const snap = addrSnapshotMap[item.addressId] || null;

        if (existing?.id) {
          const payload: Record<string, any> = {};
          if (existing.delivery_address_id !== item.addressId) {
            payload.delivery_address_id = item.addressId;
            if (snap) {
              payload.delivery_address = snap.address;
              payload.delivery_address_label = snap.label;
              payload.delivery_contact_name = snap.contact_name;
              payload.delivery_contact_phone = snap.phone;
            }
          }
          if (existing.is_locked !== desiredLocked) {
            payload.is_locked = desiredLocked;
            payload.locked_at = desiredLocked ? new Date().toISOString() : null;
          }
          if (orderId && !existing.order_id) payload.order_id = orderId;
          if (Object.keys(payload).length > 0) {
            payload.updated_at = new Date().toISOString();
            updates.push({
              id: existing.id,
              payload,
              before: existing,
              expectedUpdatedAt: existing.updated_at || null,
              needOrderSnapshot: orderId && !existing.order_id ? orderId : null
            });
          }
          return;
        }

        const itemName = item.mealType === 'breakfast' ? '早餐健康餐' : item.mealType === 'lunch' ? '午餐健康餐' : '晚餐健康餐';
        inserts.push({
          user_id: userId,
          order_id: orderId || null,
          delivery_type: 'meal',
          delivery_date: dateStr,
          meal_type: item.mealType,
          delivery_time: `${timeRange.start}-${timeRange.end}`,
          delivery_time_start: timeRange.start,
          delivery_time_end: timeRange.end,
          item_name: itemName,
          quantity: 1,
          delivery_address_id: item.addressId,
          is_locked: desiredLocked,
          locked_at: desiredLocked ? new Date().toISOString() : null,
          status: 'pending',
          updated_at: new Date().toISOString(),
          addressIdForSnapshot: item.addressId,
        });
      });

      // 拉取用户快照（nickname, phone）和订单号快照
      let userSnapshot: { nickname: string; phone: string } = { nickname: '用户', phone: '' };
      const { data: profile } = await supabase
        .from('user_profiles')
        .select('nickname, name, phone')
        .eq('user_id', userId)
        .maybeSingle();
      if (profile) {
        userSnapshot = {
          nickname: (profile.nickname || profile.name || '用户').trim() || '用户',
          phone: profile.phone || '',
        };
      }
      let orderNumberSnapshot: string | null = null;
      if (orderId) {
        const { data: ord } = await supabase
          .from('orders')
          .select('order_number')
          .eq('id', orderId)
          .maybeSingle();
        if (ord?.order_number) orderNumberSnapshot = ord.order_number;
      }

      inserts.forEach((row: any) => {
        const snap = row.addressIdForSnapshot ? addrSnapshotMap[row.addressIdForSnapshot] : null;
        delete row.addressIdForSnapshot;
        if (snap) {
          row.delivery_address = snap.address;
          row.delivery_address_label = snap.label;
          row.delivery_contact_name = snap.contact_name;
          row.delivery_contact_phone = snap.phone;
        }
        row.delivery_user_nickname = userSnapshot.nickname;
        row.delivery_user_phone = userSnapshot.phone;
        row.delivery_order_number = orderNumberSnapshot;
      });

      let insertedCount = 0;
      let updatedCount = 0;

      if (inserts.length > 0) {
        const { data: insertedRows, error: insertError } = await supabase
          .from('delivery_schedules')
          .insert(inserts)
          .select('id, user_id, delivery_date, meal_type, delivery_address_id, is_locked, locked_at, status, order_id, updated_at');
        if (insertError) {
          console.error('❌ [deliveryScheduleService] Failed to insert schedules:', insertError);
          hasErrors = true;
          errorCount += 1;
        } else {
          insertedCount = inserts.length;
          for (const row of insertedRows || []) {
            await this.logAuditEvent({
              user_id: row.user_id,
              action: 'create',
              entity_type: 'delivery_schedule',
              entity_id: row.id,
              after_data: row,
              reason: 'sync_user_delivery_schedules',
              source: 'app',
            });
          }
        }
      }

      if (updates.length > 0) {
        const orderIdsToFetch = [...new Set(updates.map((u: any) => u.needOrderSnapshot).filter(Boolean))];
        const orderNumberMap: Record<string, string> = {};
        if (orderIdsToFetch.length > 0) {
          const { data: ords } = await supabase
            .from('orders')
            .select('id, order_number')
            .in('id', orderIdsToFetch);
          (ords || []).forEach((o: any) => { orderNumberMap[o.id] = o.order_number || ''; });
        }
        for (const row of updates) {
          const payload = { ...row.payload };
          if (row.needOrderSnapshot && orderNumberMap[row.needOrderSnapshot]) {
            payload.delivery_order_number = orderNumberMap[row.needOrderSnapshot];
          }
          let updateQuery = supabase
            .from('delivery_schedules')
            .update(payload)
            .eq('id', row.id);
          if (row.expectedUpdatedAt) {
            updateQuery = updateQuery.eq('updated_at', row.expectedUpdatedAt);
          }
          const { data: updatedRow, error: updateError } = await updateQuery
            .select('id, user_id, delivery_date, meal_type, delivery_address_id, is_locked, locked_at, status, order_id, updated_at')
            .maybeSingle();
          if (updateError) {
            console.error('❌ [deliveryScheduleService] Failed to update schedule:', updateError);
            hasErrors = true;
            errorCount += 1;
          } else if (!updatedRow) {
            console.warn('⚠️ [deliveryScheduleService] Skip stale schedule update due to optimistic lock:', row.id);
            hasErrors = true;
            errorCount += 1;
          } else {
            updatedCount += 1;
            await this.logAuditEvent({
              user_id: updatedRow.user_id,
              action: 'update',
              entity_type: 'delivery_schedule',
              entity_id: updatedRow.id,
              before_data: row.before || null,
              after_data: updatedRow,
              reason: 'sync_user_delivery_schedules',
              source: 'app',
            });
          }
        }
      }

      console.log('✅ [deliveryScheduleService] Synced delivery_schedules:', {
        targetCount,
        insertedCount,
        updatedCount,
        invalidAddressCount,
        errorCount,
      });

      return {
        targetCount,
        insertedCount,
        updatedCount,
        invalidAddressCount,
        errorCount,
        hasErrors,
      };
    } catch (error) {
      console.error('❌ [deliveryScheduleService] Error in syncUserDeliverySchedules:', error);
      return {
        targetCount: 0,
        insertedCount: 0,
        updatedCount: 0,
        invalidAddressCount: 0,
        errorCount: 1,
        hasErrors: true,
      };
    }
  },
};

