      return null;
    }
  },

  async addHRVRecord(
    userId: string,
    hrvValue: number,
    status: 'excellent' | 'good' | 'fair' | 'poor',
    restingHeartRate?: number,
    notes?: string
  ): Promise<HRVRecord | null> {
