import { supabase } from '../config/supabase';
import { toLocalDateString } from '../utils/dateUtils';

export interface ExecutionReport {
  id: string;
  program_id: string;
  report_type: 'daily' | 'weekly' | 'milestone';
  report_date: string;
  report_content: {
    summary?: string;
    progress?: {
      current_day: number;
      total_days: number;
      completion_rate: number;
    };
    achievements?: string[];
    challenges?: string[];
    recommendations?: string[];
    emotional_support?: string;
    identity_reinforcement?: string;
  };
  created_at: string;
}

/**
 * 执行报告服务
 * 生成AI报告（进度解释、情绪托管、身份强化）
 */
export const executionReportService = {
  /**
   * 生成每日总结报告（使用AI生成内容）
   */
  async generateDailyReport(programId: string, reportDate: string): Promise<ExecutionReport | null> {
    try {
      console.log('🚀 [executionReportService] Generating daily report:', { programId, reportDate });

      // 🔥 确保日期格式正确（YYYY-MM-DD）
      const normalizedDate = reportDate.split('T')[0];
      console.log('📅 [executionReportService] Normalized date:', normalizedDate);

      // 🔥 获取当日任务完成情况（强制刷新，不使用缓存）
      const { data: tasks, error: tasksError } = await supabase
        .from('daily_execution_tasks')
        .select('*')
        .eq('program_id', programId)
        .eq('task_date', normalizedDate);

      if (tasksError) {
        console.error('❌ [executionReportService] Error fetching tasks:', tasksError);
        throw tasksError;
      }

      console.log('📊 [executionReportService] Tasks fetched:', {
        total: tasks?.length || 0,
        completed: tasks?.filter(t => t.task_status === 'completed').length || 0,
        skipped: tasks?.filter(t => t.task_status === 'skipped').length || 0,
        pending: tasks?.filter(t => t.task_status === 'pending').length || 0,
        tasks: tasks?.map(t => ({ id: t.id, type: t.task_type, status: t.task_status })) || [],
      });

      const completedTasks = tasks?.filter(t => t.task_status === 'completed') || [];
      const skippedTasks = tasks?.filter(t => t.task_status === 'skipped') || [];
      const totalTasks = tasks?.length || 0;
      const completionRate = totalTasks > 0 ? (completedTasks.length / totalTasks) * 100 : 0;

      console.log('📈 [executionReportService] Task stats:', {
        totalTasks,
        completedTasks: completedTasks.length,
        skippedTasks: skippedTasks.length,
        completionRate: Math.round(completionRate),
      });

      // 获取执行计划信息
      const { data: program, error: programError } = await supabase
        .from('execution_programs')
        .select('*')
        .eq('id', programId)
        .single();

      if (programError) throw programError;

      // 🔥 先检查是否已存在报告，如果存在且任务完成情况没变化，直接返回
      // （先检查，避免不必要的AI调用）
      const { data: existingReport, error: checkError } = await supabase
        .from('execution_reports')
        .select('*')
        .eq('program_id', programId)
        .eq('report_type', 'daily')
        .eq('report_date', normalizedDate)
        .maybeSingle();

      if (checkError && checkError.code !== 'PGRST116') {
        console.error('❌ [executionReportService] Error checking existing report:', checkError);
        throw checkError;
      }

      // 🔥 如果已有报告，检查任务完成情况是否有变化
      if (existingReport) {
        const existingContent = existingReport.report_content;
        const existingProgress = existingContent?.progress;

        // 比较任务完成情况
        const currentTaskStats = {
          totalTasks,
          completedTasks: completedTasks.length,
          skippedTasks: skippedTasks.length,
          completionRate: Math.round(completionRate),
        };

        const existingTaskStats = {
          totalTasks: existingProgress?.totalTasks || 0,
          completedTasks: existingProgress?.completedTasks || 0,
          skippedTasks: existingProgress?.skippedTasks || 0,
          completionRate: existingProgress?.completion_rate || 0,
        };

        // 如果任务完成情况没有变化，直接返回已有报告
        const hasTaskChanges = 
          currentTaskStats.totalTasks !== existingTaskStats.totalTasks ||
          currentTaskStats.completedTasks !== existingTaskStats.completedTasks ||
          currentTaskStats.skippedTasks !== existingTaskStats.skippedTasks ||
          currentTaskStats.completionRate !== existingTaskStats.completionRate;

        if (!hasTaskChanges) {
          console.log('✅ [executionReportService] Task stats unchanged, returning existing report:', {
            current: currentTaskStats,
            existing: existingTaskStats,
          });
          return existingReport as ExecutionReport;
        }

        console.log('🔄 [executionReportService] Task stats changed, regenerating report:', {
          current: currentTaskStats,
          existing: existingTaskStats,
        });
      }

      // 🔥 只有在没有报告或任务完成情况有变化时，才生成新报告
      // 获取最新的执行反馈数据
      const taskIds = tasks?.map(t => t.id) || [];
      let feedbacks: any[] = [];
      if (taskIds.length > 0) {
        const { data: feedbackData, error: feedbackError } = await supabase
          .from('execution_feedbacks')
          .select('*')
          .in('task_id', taskIds)
          .order('created_at', { ascending: false });

        if (!feedbackError && feedbackData) {
          feedbacks = feedbackData;
        }
      }

      // 使用AI生成报告内容（结构固定，AI填充内容）
      console.log('🤖 [executionReportService] Calling AI to generate report content...');
      const reportContent = await this.generateReportContentWithAI({
        reportType: 'daily',
        program,
        tasks,
        completedTasks,
        skippedTasks,
        totalTasks,
        completionRate,
        feedbacks,
        reportDate: normalizedDate, // 🔥 使用normalizedDate
      });

      // 确保进度数据始终存在（在AI生成之前设置，确保AI能看到正确的进度）
      reportContent.progress = {
        current_day: program.current_day,
        total_days: program.total_days,
        completion_rate: Math.round(completionRate),
        // 🔥 存储任务统计，用于下次比较
        totalTasks,
        completedTasks: completedTasks.length,
        skippedTasks: skippedTasks.length,
      };

      console.log('✅ [executionReportService] AI report content generated:', {
        hasSummary: !!reportContent.summary,
        achievementsCount: reportContent.achievements?.length || 0,
        progress: reportContent.progress,
        taskStats: { totalTasks, completedTasks: completedTasks.length, completionRate: Math.round(completionRate) },
      });

      if (existingReport) {
        // 更新现有报告（不使用.single()，因为更新可能返回0行）
        console.log('🔄 [executionReportService] Updating existing report:', existingReport.id);
        const { data: updatedReports, error: updateError } = await supabase
          .from('execution_reports')
          .update({
            report_content: reportContent,
          })
          .eq('id', existingReport.id)
          .select();

        if (updateError) {
          console.error('❌ [executionReportService] Error updating report:', updateError);
          throw updateError;
        }

        if (!updatedReports || updatedReports.length === 0) {
          console.warn('⚠️ [executionReportService] Update returned no rows (RLS issue?), returning existing report with new content');
          // 如果更新失败（可能是RLS问题），创建一个新的报告对象，使用生成的内容
          // 🔥 更新创建时间为当前时间，因为这是最新生成的内容
          const newReport = {
            ...existingReport,
            report_content: reportContent,
            created_at: new Date().toISOString(), // 🔥 更新为当前时间，表示这是最新生成的
          } as ExecutionReport;

          // 🔥 关键：验证返回的报告对象确实包含新内容
          console.log('✅ [executionReportService] Returning report with new content:', {
            reportId: newReport.id,
            progress: newReport.report_content?.progress,
            summary: newReport.report_content?.summary?.substring(0, 50) + '...',
            createdAt: newReport.created_at,
            taskStats: {
              totalTasks,
              completedTasks: completedTasks.length,
              completionRate: Math.round(completionRate),
            },
          });

          return newReport;
        }

        console.log('✅ [executionReportService] Report updated successfully');
        return updatedReports[0] as ExecutionReport;
      } else {
        // 创建新报告（使用normalizedDate）
        console.log('📝 [executionReportService] Creating new report for date:', normalizedDate);
        const { data: newReport, error: insertError } = await supabase
          .from('execution_reports')
          .insert({
            program_id: programId,
            report_type: 'daily',
            report_date: normalizedDate,
            report_content: reportContent,
          })
          .select()
          .single();

        if (insertError) {
          // 如果是重复键错误，说明记录已存在，直接查询并返回
          if (insertError.code === '23505') {
            console.warn('⚠️ [executionReportService] Duplicate key error on insert, fetching existing report');
            const { data: fetchedReport, error: fetchError } = await supabase
              .from('execution_reports')
              .select('*')
              .eq('program_id', programId)
              .eq('report_type', 'daily')
              .eq('report_date', normalizedDate)
              .maybeSingle();

            if (fetchError) {
              console.error('❌ [executionReportService] Error fetching existing report:', fetchError);
              throw insertError; // 抛出原始错误
            }

            if (fetchedReport) {
              console.log('✅ [executionReportService] Fetched existing report after duplicate error');
              return fetchedReport as ExecutionReport;
            }
          }
          console.error('❌ [executionReportService] Error inserting report:', insertError);
          throw insertError;
        }
        console.log('✅ [executionReportService] New report created successfully');
        return newReport as ExecutionReport;
      }
    } catch (error) {
      console.error('Error generating daily report:', error);
      return null;
    }
  },

  /**
