    program: any;
    tasks: any[];
    completedTasks: any[];
    skippedTasks: any[];
    totalTasks: number;
    completionRate: number;
    feedbacks: any[];
    reportDate: string;
  }): Promise<any> {
    try {
      // 构建AI提示词
      const prompt = this.buildReportPrompt(data);

      // 调用Supabase Function生成报告
      const { data: aiResponse, error: aiError } = await supabase.functions.invoke('ai-chat', {
        body: {
          message: prompt,
          conversation_id: null,
        },
      });

      if (aiError || !aiResponse?.response) {
        console.warn('⚠️ [executionReportService] AI generation failed, using fallback:', aiError);
        return this.generateFallbackReportContent(data);
      }

      // 解析AI返回的内容
      const aiContent = aiResponse.response;
      return this.parseAIReportContent(aiContent, data);
    } catch (error) {
      console.error('❌ [executionReportService] Error generating AI report:', error);
      return this.generateFallbackReportContent(data);
    }
  },

  /**
   * 构建报告生成提示词
   */
  buildReportPrompt(data: {
    reportType: 'daily' | 'weekly';
    program: any;
    tasks: any[];
    completedTasks: any[];
    skippedTasks: any[];
    totalTasks: number;
    completionRate: number;
    feedbacks: any[];
    reportDate: string;
  }): string {
    const { reportType, program, completedTasks, skippedTasks, totalTasks, completionRate, feedbacks, tasks } = data;

    const feedbackSummary = feedbacks.length > 0
      ? feedbacks.map(f => `- ${f.feedback_type}: ${JSON.stringify(f.feedback_data)}`).join('\n')
      : '无反馈数据';

    // 计算任务类型分布
    const taskTypeStats = tasks.reduce((acc: any, t: any) => {
      acc[t.task_type] = (acc[t.task_type] || 0) + 1;
      return acc;
    }, {});

    const completedTaskTypeStats = completedTasks.reduce((acc: any, t: any) => {
      acc[t.task_type] = (acc[t.task_type] || 0) + 1;
      return acc;
    }, {});

    return `你是一位专业的健康教练，需要生成一份${reportType === 'daily' ? '每日' : '每周'}执行报告。

**执行计划信息：**
- 当前天数：第${program.current_day}/${program.total_days}天
- 计划状态：${program.status}

**${reportType === 'daily' ? '今日' : '本周'}任务完成情况：**
- 总任务数：${totalTasks}
- 已完成：${completedTasks.length}
- 已跳过：${skippedTasks.length}
- 完成率：${Math.round(completionRate)}%

**任务类型分布：**
${Object.entries(taskTypeStats).map(([type, count]) => `- ${type}: ${count}个（已完成：${completedTaskTypeStats[type] || 0}个）`).join('\n')}

**已完成任务详情：**
${completedTasks.slice(0, 5).map(t => {
  if (t.task_type === 'meal') {
    return `- ${t.task_type} (${t.task_data?.meal_type || '餐食'})`;
  }
  return `- ${t.task_type}`;
}).join('\n')}
${completedTasks.length > 5 ? `... 还有${completedTasks.length - 5}个已完成任务` : ''}

**用户反馈：**
${feedbackSummary}

**请生成以下结构的报告内容（JSON格式）：**
{
  "summary": "一段简洁温暖的总结（30-50字），必须包含数据：完成了X/Y个任务，完成率Z%。加上一句温馨金句。",
  "achievements": ["简洁的成就描述1（10-15字）", "简洁的成就描述2（10-15字）", "简洁的成就描述3（10-15字）"],
  "emotional_support": "一段简洁的情绪支持（30-40字），包含温馨金句",
  "identity_reinforcement": "一段简洁的身份强化（25-35字），包含温馨金句"
}

**重要要求：**
1. **简明扼要**：所有文字都要简短精炼，不要冗长
2. **包含数据**：summary必须包含具体数据（完成了X/Y个任务，完成率Z%）
3. **温馨金句**：每个部分都要包含一句温馨、鼓励的金句（如"每一步都是进步"、"坚持就是胜利"等）
4. **语气温暖**：使用温暖、鼓励的语气，不要批评
5. **基于数据**：基于实际数据，不要编造
6. **使用第二人称"你"**
7. **只返回JSON，不要其他文字**

**示例格式：**
{
  "summary": "今天完成了3/10个任务，完成率30%。每一步都是向目标迈进，你已经很棒了！",
  "achievements": ["完成了3个任务", "坚持第21天", "继续前进"],
  "emotional_support": "没关系，明天是新的一天。重要的是持续行动，而不是完美。",
  "identity_reinforcement": "你正在成为更健康的自己，第21天的坚持值得骄傲！"
}`;
  },

  /**
   * 解析AI返回的报告内容
   */
  parseAIReportContent(aiContent: string, data: any): any {
    try {
      // 尝试提取JSON
      const jsonMatch = aiContent.match(/\{[\s\S]*\}/);
      if (jsonMatch) {
        const parsed = JSON.parse(jsonMatch[0]);
        return {
          summary: parsed.summary || '',
          achievements: Array.isArray(parsed.achievements) ? parsed.achievements : [],
          emotional_support: parsed.emotional_support || '',
          identity_reinforcement: parsed.identity_reinforcement || '',
        };
      }
    } catch (error) {
      console.warn('⚠️ [executionReportService] Failed to parse AI content, using fallback:', error);
    }

    // 如果解析失败，使用备用方案
    return this.generateFallbackReportContent(data);
  },

  /**
   * 生成备用报告内容（当AI失败时使用）
   */
  generateFallbackReportContent(data: {
    reportType: 'daily' | 'weekly';
    program: any;
    completedTasks: any[];
    skippedTasks: any[];
    totalTasks: number;
    completionRate: number;
  }): any {
    const { program, completedTasks, totalTasks, completionRate } = data;

    // 温馨金句库
    const encouragingQuotes = [
      '每一步都是进步',
      '坚持就是胜利',
      '小步快跑，持续前进',
      '今天比昨天更好',
      '你已经很棒了',
      '明天是新的一天',
      '持续行动，就是成功',
    ];

    const randomQuote = encouragingQuotes[Math.floor(Math.random() * encouragingQuotes.length)];

    return {
      summary: `今天完成了${completedTasks.length}/${totalTasks}个任务，完成率${Math.round(completionRate)}%。${randomQuote}！`,
      achievements: completedTasks.slice(0, 3).map(t => {
        if (t.task_type === 'meal') {
          return `完成了${t.task_data?.meal_type || '餐食'}任务`;
        }
        return `完成了${t.task_type}任务`;
      }),
      emotional_support: completionRate >= 80
        ? `你做得很好！每一步都是向目标迈进。${randomQuote}！`
        : `没关系，明天是新的一天。重要的是持续行动，而不是完美。${randomQuote}！`,
      identity_reinforcement: `你正在成为更健康的自己。第${program.current_day}天的坚持值得骄傲！${randomQuote}！`,
    };
  },
};

import { supabase } from '../config/supabase';
import { toBeijingDateString } from '../utils/dateUtils';

export interface DailyExecutionTask {
  id: string;
  program_id: string;
  task_date: string;
  task_type: 'meal' | 'exercise' | 'water' | 'sleep' | 'checkin' | 'notification';
  task_status: 'pending' | 'completed' | 'skipped';
  scheduled_time: string | null;
  completed_at: string | null;
  task_data: Record<string, any> & {
    // 通知类型相关字段
    notification_type?: 'delivery_received' | 'meal_consumed' | 'nutrition_synced' | 'blood_glucose_recorded' | 'time_since_last_meal';
    delivery_schedule_id?: string;
    meal_type?: string;
    hours_since_last_meal?: number;
  };
  created_at: string;
  updated_at: string;
}

/**
 * 每日任务服务
 * 基于配送计划自动生成任务流
 */
export const executionTaskService = {
  /**
   * 基于配送计划自动生成每日任务
   */
  async generateDailyTasks(
    programId: string,
    taskDate: string,
    mealDeliverySchedules?: Array<{
      id?: string;
      delivery_date: string;
      meal_type: string;
      delivery_time_start?: string;
    }>
  ): Promise<DailyExecutionTask[]> {
    try {
      console.log('🚀 [executionTaskService] Starting task generation:', {
        programId,
        taskDate,
        hasSchedules: !!mealDeliverySchedules,
        scheduleCount: mealDeliverySchedules?.length || 0,
      });

      const tasks: Omit<DailyExecutionTask, 'id' | 'created_at' | 'updated_at'>[] = [];

      // 1. 生成餐食相关通知任务（基于配送计划）
      if (mealDeliverySchedules && mealDeliverySchedules.length > 0) {
        const daySchedules = mealDeliverySchedules.filter(
          schedule => schedule.delivery_date === taskDate
        );

        for (const schedule of daySchedules) {
          const mealType = schedule.meal_type; // breakfast, lunch, dinner
          const deliveryTime = schedule.delivery_time_start || this.getDefaultMealTime(mealType);

          // 只处理中餐和晚餐（根据用户需求）
          if (mealType !== 'lunch' && mealType !== 'dinner') {
            continue;
          }

          // 计算各个通知的时间点
          // delivery_time_start 可能是 "HH:MM" 或 "HH:MM:SS" 格式
          const deliveryTimeParts = deliveryTime.split(':');
          const deliveryHour = parseInt(deliveryTimeParts[0]);
          const deliveryMinute = parseInt(deliveryTimeParts[1] || '0');

          // 1. 已收到配送 - 配送时间
          tasks.push({
            program_id: programId,
            task_date: taskDate,
            task_type: 'notification',
            task_status: 'pending',
            scheduled_time: `${String(deliveryHour).padStart(2, '0')}:${String(deliveryMinute).padStart(2, '0')}:00`,
            completed_at: null,
            task_data: {
              notification_type: 'delivery_received',
              meal_type: mealType,
              delivery_schedule_id: schedule.id || schedule.delivery_date,
            },
          });

          // 2. 已用完中餐/晚餐 - 配送时间后1小时
          const consumeHour = (deliveryHour + 1) % 24;
          const consumeTime = `${String(consumeHour).padStart(2, '0')}:${String(deliveryMinute).padStart(2, '0')}:00`;
          tasks.push({
            program_id: programId,
            task_date: taskDate,
            task_type: 'notification',
            task_status: 'pending',
            scheduled_time: consumeTime,
            completed_at: null,
            task_data: {
              notification_type: 'meal_consumed',
              meal_type: mealType,
              delivery_schedule_id: schedule.id || schedule.delivery_date,
            },
          });

          // 3. 已同步营养素及卡路里 - 用餐后立即（+10分钟）
          // 🔥 修复：基于消费时间（consumeHour）计算，而不是配送时间
          const nutritionMinute = deliveryMinute + 10;
          const nutritionHour = nutritionMinute >= 60 ? (consumeHour + Math.floor(nutritionMinute / 60)) % 24 : consumeHour;
          const nutritionTime = `${String(nutritionHour).padStart(2, '0')}:${String(nutritionMinute % 60).padStart(2, '0')}:00`;
          tasks.push({
            program_id: programId,
            task_date: taskDate,
            task_type: 'notification',
            task_status: 'pending',
            scheduled_time: nutritionTime,
            completed_at: null,
            task_data: {
              notification_type: 'nutrition_synced',
              meal_type: mealType,
              delivery_schedule_id: schedule.id || schedule.delivery_date,
            },
          });

          // 4. 已记录餐后2小时血糖 - 用餐后2小时
          const glucoseMinute = deliveryMinute + 120;
          const glucoseHour = glucoseMinute >= 60 ? (consumeHour + Math.floor(glucoseMinute / 60)) % 24 : consumeHour;
          const glucoseTime = `${String(glucoseHour).padStart(2, '0')}:${String(glucoseMinute % 60).padStart(2, '0')}:00`;
          tasks.push({
            program_id: programId,
            task_date: taskDate,
            task_type: 'notification',
            task_status: 'pending',
            scheduled_time: glucoseTime,
            completed_at: null,
            task_data: {
              notification_type: 'blood_glucose_recorded',
              meal_type: mealType,
              delivery_schedule_id: schedule.id || schedule.delivery_date,
            },
          });
        }

        // 5. 已多长时间没有进食 - 动态计算，放在午餐和晚餐的中间时间点
        // 如果有午餐，在午餐后3小时提醒；如果有晚餐，在晚餐后3小时提醒
        const lunchSchedule = daySchedules.find(s => s.meal_type === 'lunch');
        const dinnerSchedule = daySchedules.find(s => s.meal_type === 'dinner');

        if (lunchSchedule) {
          const lunchTime = lunchSchedule.delivery_time_start || this.getDefaultMealTime('lunch');
          const lunchParts = lunchTime.split(':');
          const lunchHour = parseInt(lunchParts[0]);
          const lunchMinute = parseInt(lunchParts[1] || '0');
          // 午餐后3小时提醒
          const reminderHour = (lunchHour + 3) % 24;
          const reminderTime = `${String(reminderHour).padStart(2, '0')}:${String(lunchMinute).padStart(2, '0')}:00`;
          tasks.push({
            program_id: programId,
            task_date: taskDate,
            task_type: 'notification',
            task_status: 'pending',
            scheduled_time: reminderTime,
            completed_at: null,
            task_data: {
              notification_type: 'time_since_last_meal',
              meal_type: 'lunch',
              hours_since_last_meal: 3,
              delivery_schedule_id: lunchSchedule.id || lunchSchedule.delivery_date,
            },
          });
        }
      } else {
        // 如果没有配送计划，仅生成 3 条：餐食配送通知、数据同步通知、日反馈通知（由 baseTasks checkin 提供）
        const timeLunch = this.getDefaultMealTime('lunch');
        const [hourL, minL] = timeLunch.split(':').map((s, i) => (i === 0 ? parseInt(s, 10) : parseInt(s || '0', 10)));
        const timeDinner = this.getDefaultMealTime('dinner');
        const [hourD, minD] = timeDinner.split(':').map((s, i) => (i === 0 ? parseInt(s, 10) : parseInt(s || '0', 10)));

        // 1. 餐食配送通知（午餐配送时间）
        tasks.push({
          program_id: programId,
          task_date: taskDate,
          task_type: 'notification',
          task_status: 'pending',
          scheduled_time: `${String(hourL).padStart(2, '0')}:${String(minL).padStart(2, '0')}:00`,
          completed_at: null,
          task_data: { notification_type: 'delivery_received', meal_type: 'lunch' },
        });

        // 2. 数据同步通知（晚餐用餐后+10分钟）
        const consumeHourD = (hourD + 1) % 24;
        const nutritionMinD = minD + 10;
        const nutritionHourD = nutritionMinD >= 60 ? (consumeHourD + 1) % 24 : consumeHourD;
        tasks.push({
          program_id: programId,
          task_date: taskDate,
          task_type: 'notification',
          task_status: 'pending',
          scheduled_time: `${String(nutritionHourD).padStart(2, '0')}:${String(nutritionMinD % 60).padStart(2, '0')}:00`,
          completed_at: null,
          task_data: { notification_type: 'nutrition_synced', meal_type: 'dinner' },
        });
      }

      // 2. 生成其他任务（运动、喝水、睡眠、打卡）
      const baseTasks = [
        {
          program_id: programId,
          task_date: taskDate,
          task_type: 'water' as const,
          task_status: 'pending' as const,
          scheduled_time: '09:00:00',
          completed_at: null,
          task_data: {},
        },
        {
          program_id: programId,
          task_date: taskDate,
          task_type: 'exercise' as const,
          task_status: 'pending' as const,
          scheduled_time: '18:00:00',
          completed_at: null,
          task_data: {},
        },
        {
          program_id: programId,
          task_date: taskDate,
          task_type: 'sleep' as const,
          task_status: 'pending' as const,
          scheduled_time: '22:00:00',
          completed_at: null,
          task_data: {},
        },
        {
          program_id: programId,
          task_date: taskDate,
          task_type: 'checkin' as const,
          task_status: 'pending' as const,
          scheduled_time: '20:00:00',
          completed_at: null,
          task_data: { checkin_subtype: 'smile' },
        },
        {
          program_id: programId,
          task_date: taskDate,
          task_type: 'checkin' as const,
          task_status: 'pending' as const,
          // 避免命中 unique(program_id, task_date, task_type, scheduled_time)
          // 与另一条 checkin 区分时间，防止整批插入失败
          scheduled_time: '20:05:00',
          completed_at: null,
          task_data: { checkin_subtype: 'breathe' },
        },
      ];
      tasks.push(...baseTasks);
      console.log('📝 [executionTaskService] Generated base tasks:', baseTasks.length, 'Total tasks so far:', tasks.length);

      // 3. 检查任务是否已存在，避免重复创建
      // 🔥 修复：统一时间格式，与显示逻辑保持一致（只取HH:MM，忽略秒）
      const normalizeTime = (time: string | null | undefined): string => {
        if (!time) return '';
        const match = time.match(/^(\d{1,2}):(\d{2})/);
        if (match) {
          return `${match[1].padStart(2, '0')}:${match[2]}`;
        }
        return '';
      };

      const existingTasks = await this.getTasksByDate(programId, taskDate);
      const existingTaskKeys = new Set(
        existingTasks.map(t => {
          // 🔥 确保 task_data 是对象
          let taskData = t.task_data;
          if (typeof taskData === 'string') {
            try {
              taskData = JSON.parse(taskData);
            } catch (e) {
              taskData = {};
            }
          }
          if (!taskData || typeof taskData !== 'object') {
            taskData = {};
          }

          const notificationType = taskData?.notification_type;
          const checkinSubtype = taskData?.checkin_subtype;
          const normalizedTime = normalizeTime(t.scheduled_time);
          if (notificationType) {
            return `${t.task_type}-${notificationType}-${taskData?.meal_type || ''}-${normalizedTime}`;
          }
          if (t.task_type === 'checkin' && checkinSubtype) {
            return `${t.task_type}-${checkinSubtype}-${normalizedTime}`;
          }
          return `${t.task_type}-${normalizedTime}`;
        })
      );

      const tasksToInsert = tasks.filter(task => {
        // 🔥 确保 task_data 是对象
        let taskData = task.task_data;
        if (typeof taskData === 'string') {
          try {
            taskData = JSON.parse(taskData);
          } catch (e) {
            taskData = {};
          }
        }
        if (!taskData || typeof taskData !== 'object') {
          taskData = {};
        }

        const notificationType = taskData?.notification_type;
        const checkinSubtype = taskData?.checkin_subtype;
        const normalizedTime = normalizeTime(task.scheduled_time);
        if (notificationType) {
          const key = `${task.task_type}-${notificationType}-${taskData?.meal_type || ''}-${normalizedTime}`;
          const exists = existingTaskKeys.has(key);
          if (exists) {
            console.log('⚠️ [executionTaskService] Duplicate task detected, skipping:', key, {
              task_type: task.task_type,
              notification_type: notificationType,
              meal_type: taskData?.meal_type,
              scheduled_time: task.scheduled_time,
              normalized_time: normalizedTime,
            });
          }
          return !exists;
        }
        const key = task.task_type === 'checkin' && checkinSubtype
          ? `${task.task_type}-${checkinSubtype}-${normalizedTime}`
          : `${task.task_type}-${normalizedTime}`;
        const exists = existingTaskKeys.has(key);
        if (exists) {
          console.log('⚠️ [executionTaskService] Duplicate task detected, skipping:', key, {
            task_type: task.task_type,
            scheduled_time: task.scheduled_time,
            normalized_time: normalizedTime,
          });
        }
        return !exists;
      });

      if (tasksToInsert.length === 0) {
        console.log('ℹ️ [executionTaskService] No new tasks to insert, returning existing tasks:', existingTasks.length);
        return existingTasks;
      }

      console.log('💾 [executionTaskService] Inserting tasks:', tasksToInsert.length);
      // 🔥 调试：打印要插入的任务详情
      if (tasksToInsert.length > 0) {
        console.log('📋 [executionTaskService] Tasks to insert:', tasksToInsert.map(t => ({
          type: t.task_type,
          notification_type: t.task_data?.notification_type,
          meal_type: t.task_data?.meal_type,
          scheduled_time: t.scheduled_time,
        })));
      }

      // 4. 批量插入新任务
      const { data: insertedTasks, error } = await supabase
        .from('daily_execution_tasks')
        .insert(tasksToInsert)
        .select();

      if (error) {
        console.error('❌ [executionTaskService] Error inserting tasks:', error);
        // 兼容唯一键冲突：按数据库真实唯一键(task_type + time)重试一次
        if (error.code === '23505') {
          try {
            const latestExistingTasks = await this.getTasksByDate(programId, taskDate);
            const existingDbUniqueKeys = new Set(
              latestExistingTasks.map((t) => `${t.task_type}-${normalizeTime(t.scheduled_time)}`)
            );
            const seenRetryKeys = new Set<string>();
            const retryTasks = tasksToInsert.filter((t) => {
              const key = `${t.task_type}-${normalizeTime(t.scheduled_time)}`;
              if (existingDbUniqueKeys.has(key)) return false;
              if (seenRetryKeys.has(key)) return false;
              seenRetryKeys.add(key);
              return true;
            });
            if (retryTasks.length > 0) {
              const { data: retryInserted, error: retryError } = await supabase
                .from('daily_execution_tasks')
                .insert(retryTasks)
                .select();
              if (!retryError) {
                const retryResult = [...latestExistingTasks, ...(retryInserted || [])] as DailyExecutionTask[];
                console.log('✅ [executionTaskService] Retry after unique conflict success:', retryResult.length);
                return retryResult;
              }
              console.error('❌ [executionTaskService] Retry after unique conflict failed:', retryError);
            }
          } catch (retryCatchError) {
            console.error('❌ [executionTaskService] Retry logic crashed:', retryCatchError);
          }
        }

        // 兼容旧库：如果 notification 任务类型不受支持，降级为仅插入基础任务（water/exercise/sleep/checkin）
        if (error.code === '23514' || error.message?.includes('task_type')) {
          const fallbackTasks = tasksToInsert.filter((t) => t.task_type !== 'notification');
          if (fallbackTasks.length > 0) {
            console.warn('⚠️ [executionTaskService] notification task_type unsupported, fallback to base tasks only');
            const { data: fallbackInserted, error: fallbackError } = await supabase
              .from('daily_execution_tasks')
              .insert(fallbackTasks)
              .select();
            if (!fallbackError) {
              const fallbackResult = [...existingTasks, ...(fallbackInserted || [])] as DailyExecutionTask[];
              console.log('✅ [executionTaskService] Fallback generation success:', fallbackResult.length);
              return fallbackResult;
            }
            console.error('❌ [executionTaskService] Fallback insert failed:', fallbackError);
          }

          const friendlyError = new Error('任务生成失败：当前数据库缺少 notification 任务类型支持，请联系管理员执行对应迁移。');
          (friendlyError as any).originalError = error;
          throw friendlyError;
        }
        throw error;
      }

      const result = [...existingTasks, ...(insertedTasks || [])] as DailyExecutionTask[];
      console.log('✅ [executionTaskService] Successfully generated tasks:', result.length);
      return result;
    } catch (error) {
      console.error('Error generating daily tasks:', error);
      throw error;
    }
  },

  /**
   * 获取默认餐食时间
   */
  getDefaultMealTime(mealType: string): string {
    const times: Record<string, string> = {
      breakfast: '08:00:00',
      lunch: '12:00:00',
      dinner: '18:00:00',
    };
    return times[mealType] || '12:00:00';
  },

  /**
   * 获取指定日期的所有任务
   */
  async getTasksByDate(programId: string, taskDate: string): Promise<DailyExecutionTask[]> {
    try {
      console.log('🔍 [executionTaskService] Fetching tasks for:', { programId, taskDate });
      const { data, error } = await supabase
        .from('daily_execution_tasks')
        .select('*')
        .eq('program_id', programId)
        .eq('task_date', taskDate)
        .order('scheduled_time', { ascending: true });

      if (error) {
        console.error('❌ [executionTaskService] Error fetching tasks:', error);
        throw error;
      }

      console.log('✅ [executionTaskService] Fetched tasks:', data?.length || 0);
      return (data || []) as DailyExecutionTask[];
    } catch (error) {
      console.error('❌ [executionTaskService] Error getting tasks by date:', error);
      return [];
    }
  },

  /**
   * 获取下一个待执行任务
   */
  async getNextTask(programId: string, taskDate?: string): Promise<DailyExecutionTask | null> {
    try {
      const today = taskDate || toBeijingDateString(new Date());

      const { data, error } = await supabase
        .from('daily_execution_tasks')
        .select('*')
        .eq('program_id', programId)
        .eq('task_date', today)
        .eq('task_status', 'pending')
        .order('scheduled_time', { ascending: true })
        .limit(1)
        .maybeSingle();

      if (error && error.code !== 'PGRST116') {
        throw error;
      }

      return data as DailyExecutionTask | null;
    } catch (error) {
      console.error('Error getting next task:', error);
      return null;
    }
  },

  /**
   * 标记任务完成（自动降级处理）
   * 合并 completionData 到现有 task_data，避免覆写 notification_type 等关键字段
   */
  async markTaskComplete(
    taskId: string,
    completionData?: Record<string, any>
  ): Promise<DailyExecutionTask | null> {
    try {
      const { data: existing, error: fetchErr } = await supabase
        .from('daily_execution_tasks')
        .select('task_data')
        .eq('id', taskId)
        .maybeSingle();

      if (fetchErr) throw fetchErr;

      let taskData: Record<string, any> = {};
      if (existing?.task_data) {
        taskData = typeof existing.task_data === 'string'
          ? (() => { try { return JSON.parse(existing.task_data); } catch { return {}; } })()
          : { ...existing.task_data };
      }
      if (completionData && typeof completionData === 'object') {
        taskData = { ...taskData, ...completionData };
      }

      const { data, error } = await supabase
        .from('daily_execution_tasks')
        .update({
          task_status: 'completed',
          completed_at: new Date().toISOString(),
          task_data: taskData,
          updated_at: new Date().toISOString(),
        })
        .eq('id', taskId)
        .select()
        .single();

      if (error) throw error;
      return data as DailyExecutionTask;
    } catch (error) {
      console.error('Error marking task complete:', error);
      return null;
    }
  },

  /**
   * 跳过任务（降级处理）
   */
  async skipTask(taskId: string): Promise<DailyExecutionTask | null> {
    try {
      const { data, error } = await supabase
        .from('daily_execution_tasks')
        .update({
          task_status: 'skipped',
          updated_at: new Date().toISOString(),
        })
        .eq('id', taskId)
        .select()
        .single();

      if (error) throw error;
      return data as DailyExecutionTask;
    } catch (error) {
      console.error('Error skipping task:', error);
      return null;
    }
  },

  /**
   * 获取今日所有任务
   */
  async getTodayTasks(programId: string): Promise<DailyExecutionTask[]> {
    const today = toBeijingDateString(new Date());
    return this.getTasksByDate(programId, today);
  },

  /**
   * 清理重复任务（保留第一个，删除其他重复的）
   */
  async cleanupDuplicateTasks(programId: string, taskDate: string): Promise<number> {
    try {
      const tasks = await this.getTasksByDate(programId, taskDate);
      const taskMap = new Map<string, DailyExecutionTask>();
      const duplicates: string[] = [];

      for (const task of tasks) {
        // 生成去重key（与显示逻辑一致）
        let taskData = task.task_data;
        if (typeof taskData === 'string') {
          try {
            taskData = JSON.parse(taskData);
          } catch (e) {
            taskData = {};
          }
        }
        if (!taskData || typeof taskData !== 'object') {
          taskData = {};
        }

        // 统一时间格式
        const normalizeTime = (time: string | null | undefined): string => {
          if (!time) return '';
          const match = time.match(/^(\d{1,2}):(\d{2})/);
          if (match) {
            return `${match[1].padStart(2, '0')}:${match[2]}`;
          }
          return '';
        };

        let key: string;
        if (task.task_type === 'notification' && taskData?.notification_type) {
          const normalizedTime = normalizeTime(task.scheduled_time);
          key = `${task.task_type}-${taskData.notification_type}-${taskData.meal_type || ''}-${normalizedTime}`;
        } else {
          const normalizedTime = normalizeTime(task.scheduled_time);
          key = `${task.task_type}-${normalizedTime}`;
        }

        if (taskMap.has(key)) {
          // 发现重复，保留第一个（或已完成的那个）
          const existing = taskMap.get(key)!;
          console.log('🔍 [cleanupDuplicateTasks] Found duplicate:', {
            key,
            existing_id: existing.id,
            existing_status: existing.task_status,
            new_id: task.id,
            new_status: task.task_status,
            notification_type: taskData?.notification_type,
            meal_type: taskData?.meal_type,
            scheduled_time: task.scheduled_time,
          });

          if (existing.task_status === 'completed' && task.task_status !== 'completed') {
            // 已存在的已完成，新的是未完成，删除新的
            duplicates.push(task.id);
          } else if (existing.task_status !== 'completed' && task.task_status === 'completed') {
            // 新的是已完成，已存在的是未完成，删除已存在的，保留新的
            duplicates.push(existing.id);
            taskMap.set(key, task);
          } else {
            // 状态相同，保留第一个（按创建时间，或ID较小的），删除新的
            // 比较创建时间，保留较早的
            const existingTime = new Date(existing.created_at || 0).getTime();
            const newTime = new Date(task.created_at || 0).getTime();
            if (newTime < existingTime) {
              // 新的更早，删除已存在的，保留新的
              duplicates.push(existing.id);
              taskMap.set(key, task);
            } else {
              // 已存在的更早，删除新的
              duplicates.push(task.id);
            }
          }
        } else {
          taskMap.set(key, task);
        }
      }

      if (duplicates.length > 0) {
        console.log(`🧹 [executionTaskService] Cleaning up ${duplicates.length} duplicate tasks`);
        const { error } = await supabase
          .from('daily_execution_tasks')
          .delete()
          .in('id', duplicates);

        if (error) {
          console.error('❌ [executionTaskService] Error deleting duplicate tasks:', error);
          throw error;
        }
        console.log(`✅ [executionTaskService] Deleted ${duplicates.length} duplicate tasks`);
      }

      return duplicates.length;
    } catch (error) {
      console.error('❌ [executionTaskService] Error cleaning up duplicate tasks:', error);
      return 0;
    }
  },

  /**
   * 修复旧任务数据：为缺少 notification_type 的任务添加正确的值
   */
  async fixMissingNotificationTypes(programId: string, taskDate: string): Promise<number> {
    try {
      const tasks = await this.getTasksByDate(programId, taskDate);
      let fixedCount = 0;
      const updates: Array<{ id: string; task_data: any }> = [];

      for (const task of tasks) {
        if (task.task_type !== 'notification') continue;

        let taskData = task.task_data;
        if (typeof taskData === 'string') {
          try {
            taskData = JSON.parse(taskData);
          } catch (e) {
            taskData = {};
          }
        }
        if (!taskData || typeof taskData !== 'object') {
          taskData = {};
        }

        // 如果已经有 notification_type，跳过
        if (taskData.notification_type) continue;

        // 根据其他字段推断 notification_type
        let notificationType: string | null = null;

        // 1. 检查是否有 delivery_schedule_id -> delivery_received
        if (taskData.delivery_schedule_id) {
          notificationType = 'delivery_received';
        }
        // 2. 检查是否有 meal_type 但没有其他标识 -> meal_consumed
        else if (taskData.meal_type) {
          notificationType = 'meal_consumed';
        }
        // 3. 根据时间推断
        else if (task.scheduled_time) {
          const timeStr = task.scheduled_time.substring(0, 5);
          const hour = parseInt(timeStr.split(':')[0]);
          // 根据时间推断，默认是 meal_consumed
          notificationType = 'meal_consumed';
        }

        if (notificationType) {
          const updatedTaskData = {
            ...taskData,
            notification_type: notificationType,
          };
          updates.push({
            id: task.id,
            task_data: updatedTaskData,
          });
          fixedCount++;
        }
      }

      // 批量更新
      if (updates.length > 0) {
        console.log(`🔧 [executionTaskService] Fixing ${updates.length} tasks with missing notification_type`);
        for (const update of updates) {
          const { error } = await supabase
            .from('daily_execution_tasks')
            .update({
              task_data: update.task_data,
              updated_at: new Date().toISOString(),
            })
            .eq('id', update.id);

          if (error) {
            console.error(`❌ [executionTaskService] Error updating task ${update.id}:`, error);
          }
        }
        console.log(`✅ [executionTaskService] Fixed ${fixedCount} tasks`);
      }

      return fixedCount;
    } catch (error) {
      console.error('❌ [executionTaskService] Error fixing missing notification types:', error);
      return 0;
    }
  },

  /**
   * 完成摄入后插入 3 条实时通知：已完成X餐摄入、已自动同步X餐热量及营养元素、再过2小时我会自动记录血糖值
   */
  async insertMealIntakeNotifications(
    programId: string,
    taskDate: string,
    mealType: string,
    mealLabel: string
  ): Promise<void> {
    const now = new Date();
    const nowMin = now.getHours() * 60 + now.getMinutes();
    const nowStr = `${String(now.getHours()).padStart(2, '0')}:${String(now.getMinutes()).padStart(2, '0')}:00`;
    const laterMin = nowMin + 120; // 2小时
    const laterHour = Math.floor(laterMin / 60) % 24;
    const laterMinute = laterMin % 60;
    const laterStr = `${String(laterHour).padStart(2, '0')}:${String(laterMinute).padStart(2, '0')}:00`;

    const tasksToInsert = [
      {
        program_id: programId,
        task_date: taskDate,
        task_type: 'notification' as const,
        task_status: 'completed' as const,
        scheduled_time: nowStr,
        completed_at: new Date().toISOString(),
        task_data: {
          notification_type: 'meal_consumed',
          meal_type: mealType,
          custom_label: `已完成${mealLabel}摄入`,
        },
      },
      {
        program_id: programId,
        task_date: taskDate,
        task_type: 'notification' as const,
        task_status: 'completed' as const,
        scheduled_time: nowStr,
        completed_at: new Date().toISOString(),
        task_data: {
          notification_type: 'nutrition_synced',
          meal_type: mealType,
          custom_label: `已自动同步${mealLabel}热量及营养元素`,
        },
      },
      {
        program_id: programId,
        task_date: taskDate,
        task_type: 'notification' as const,
        task_status: 'pending' as const,
        scheduled_time: laterStr,
        completed_at: null,
        task_data: {
          notification_type: 'blood_glucose_recorded',
          meal_type: mealType,
          custom_label: '再过2小时，我会自动记录血糖值',
        },
      },
    ];

    const { error } = await supabase
      .from('daily_execution_tasks')
      .insert(tasksToInsert);

    if (error) {
      console.error('❌ [executionTaskService] Error inserting meal intake notifications:', error);
      throw error;
    }
  },
};

import { supabase } from '../config/supabase';

export interface ExerciseRecord {
  id?: string;
  user_id?: string;
  exercise_name: string;
  exercise_type?: string;
  duration: number;
  calories_burned: number;
  intensity?: string;
  notes?: string;
  recorded_at: string;
  icon?: string;
  originalId?: string;
  source?: 'ai' | 'manual';
}

function buildExerciseDataPayload(exercise: ExerciseRecord): Record<string, unknown> {
  return {
    name: exercise.exercise_name,
    exercise_type: exercise.exercise_type || 'other',
    duration: exercise.duration,
    calories_burned: exercise.calories_burned,
    intensity: exercise.intensity || 'moderate',
    icon: exercise.icon,
    originalId: exercise.originalId,
    source: exercise.source || 'manual',
  };
}

const mapHealthRowToExerciseRecord = (row: any): ExerciseRecord => {
  const ed = row.exercise_data && typeof row.exercise_data === 'object' ? row.exercise_data : {};
  let parsedNotes: { icon?: string; originalId?: string } = {};
  const isLikelyJSON = (s: string) => {
    const t = s.trim();
    return t.startsWith('{') || t.startsWith('[');
  };
  if (row.notes && typeof row.notes === 'string' && isLikelyJSON(row.notes)) {
    try {
      parsedNotes = JSON.parse(row.notes);
    } catch {
      parsedNotes = {};
    }
  }

  let source: 'ai' | 'manual' = (ed.source as 'ai' | 'manual') || 'manual';
  if (ed.source !== 'ai' && ed.source !== 'manual' && row.notes) {
    const notesStr = typeof row.notes === 'string' ? row.notes : JSON.stringify(row.notes);
    if (notesStr.includes('AI记录') || notesStr.includes('AI创建') || notesStr.includes('AI识别')) {
      source = 'ai';
    }
  }

  return {
    id: row.id,
    user_id: row.user_id,
    exercise_name: (ed.name as string) || '运动',
    exercise_type: (ed.exercise_type as string) || 'other',
    duration: Number(ed.duration) || 0,
    calories_burned: Number(ed.calories_burned ?? row.value ?? 0) || 0,
    intensity: ed.intensity as string | undefined,
    notes: row.notes,
    recorded_at: row.recorded_at,
    icon: (ed.icon as string) || parsedNotes.icon,
    originalId: (ed.originalId as string) || parsedNotes.originalId,
    source,
  };
};

export const exerciseService = {
  async addExercise(exercise: ExerciseRecord) {
    const { data: { user } } = await supabase.auth.getUser();

    if (!user) {
      throw new Error('User not authenticated');
    }

    const exerciseData = buildExerciseDataPayload({ ...exercise, source: exercise.source || 'manual' });

    const { data, error } = await supabase
      .from('health_records')
      .insert({
        user_id: user.id,
        record_type: 'exercise',
        value: exercise.calories_burned ?? 0,
        unit: 'kcal',
        exercise_data: exerciseData,
        notes:
          exercise.notes ||
          JSON.stringify({
            icon: exercise.icon,
            originalId: exercise.originalId,
          }),
        recorded_at: exercise.recorded_at,
      })
      .select()
      .single();

    if (error) {
      console.error('Error adding exercise:', error);
      throw error;
    }

    return mapHealthRowToExerciseRecord(data);
  },

  async addMultipleExercises(exercises: ExerciseRecord[]) {
    const { data: { user } } = await supabase.auth.getUser();

    if (!user) {
      throw new Error('User not authenticated');
    }

    const rows = exercises.map((exercise) => {
      const exerciseData = buildExerciseDataPayload({ ...exercise, source: exercise.source || 'manual' });
      return {
        user_id: user.id,
        record_type: 'exercise' as const,
        value: exercise.calories_burned ?? 0,
        unit: 'kcal',
        exercise_data: exerciseData,
        notes:
          exercise.notes ||
          JSON.stringify({
            icon: exercise.icon,
            originalId: exercise.originalId,
          }),
        recorded_at: exercise.recorded_at,
      };
    });

    const { data, error } = await supabase.from('health_records').insert(rows).select();

    if (error) {
      console.error('Error adding exercises:', error);
      throw error;
    }

    return (data || []).map(mapHealthRowToExerciseRecord);
  },

  async getExercisesByDateRange(startDate: string, endDate: string) {
    const { data: { user } } = await supabase.auth.getUser();

    if (!user) {
      throw new Error('User not authenticated');
    }

    const { data, error } = await supabase
      .from('health_records')
      .select('*')
      .eq('user_id', user.id)
      .eq('record_type', 'exercise')
      .gte('recorded_at', startDate)
      .lte('recorded_at', endDate)
      .order('recorded_at', { ascending: false });

    if (error) {
      console.error('Error fetching exercises:', error);
      throw error;
    }

    return (data || []).map(mapHealthRowToExerciseRecord);
  },

  async getExercisesByDate(date: string) {
    const { data: { user } } = await supabase.auth.getUser();

    if (!user) {
      throw new Error('User not authenticated');
    }

    const startOfDay = new Date(date);
    startOfDay.setHours(0, 0, 0, 0);

    const endOfDay = new Date(date);
    endOfDay.setHours(23, 59, 59, 999);

    const { data, error } = await supabase
      .from('health_records')
      .select('*')
      .eq('user_id', user.id)
      .eq('record_type', 'exercise')
      .gte('recorded_at', startOfDay.toISOString())
      .lte('recorded_at', endOfDay.toISOString())
      .order('recorded_at', { ascending: false });

    if (error) {
      console.error('Error fetching exercises:', error);
      throw error;
    }

    return (data || []).map(mapHealthRowToExerciseRecord);
  },

  async deleteExercise(id: string) {
    const { data: { user } } = await supabase.auth.getUser();

    if (!user) {
      throw new Error('User not authenticated');
    }

    const { error } = await supabase
      .from('health_records')
      .delete()
      .eq('id', id)
      .eq('user_id', user.id)
      .eq('record_type', 'exercise');

    if (error) {
      console.error('Error deleting exercise:', error);
      throw error;
    }
  },

  async updateExercise(id: string, updates: Partial<ExerciseRecord>) {
    const { data: { user } } = await supabase.auth.getUser();

    if (!user) {
      throw new Error('User not authenticated');
    }

    const { data: existing, error: fetchError } = await supabase
      .from('health_records')
      .select('exercise_data, notes')
      .eq('id', id)
      .eq('user_id', user.id)
      .eq('record_type', 'exercise')
      .maybeSingle();

    if (fetchError) {
      console.error('Error loading exercise for update:', fetchError);
      throw fetchError;
    }
    if (!existing) {
      throw new Error('Exercise record not found');
    }

    const prev = (existing.exercise_data && typeof existing.exercise_data === 'object'
      ? existing.exercise_data
      : {}) as Record<string, unknown>;

    const next: Record<string, unknown> = { ...prev };
    if (updates.exercise_name !== undefined) next.name = updates.exercise_name;
    if (updates.exercise_type !== undefined) next.exercise_type = updates.exercise_type;
    if (updates.duration !== undefined) next.duration = updates.duration;
    if (updates.calories_burned !== undefined) next.calories_burned = updates.calories_burned;
    if (updates.intensity !== undefined) next.intensity = updates.intensity;
    if (updates.icon !== undefined) next.icon = updates.icon;
    if (updates.originalId !== undefined) next.originalId = updates.originalId;
    if (updates.source !== undefined) next.source = updates.source;

    const calories =
      updates.calories_burned !== undefined
        ? updates.calories_burned
        : Number(next.calories_burned ?? prev.calories_burned ?? 0);

    let notes = existing?.notes as string | undefined;
    if (updates.icon !== undefined || updates.originalId !== undefined) {
      notes = JSON.stringify({
        icon: updates.icon ?? next.icon,
        originalId: updates.originalId ?? next.originalId,
      });
    }
    if (updates.notes !== undefined) notes = updates.notes;

    const patch: Record<string, unknown> = {
      exercise_data: next,
      value: calories,
      unit: 'kcal',
      updated_at: new Date().toISOString(),
    };
    if (updates.recorded_at) patch.recorded_at = updates.recorded_at;
    if (notes !== undefined) patch.notes = notes;

    const { data, error } = await supabase
      .from('health_records')
      .update(patch)
      .eq('id', id)
      .eq('user_id', user.id)
      .eq('record_type', 'exercise')
      .select()
      .single();

    if (error) {
      console.error('Error updating exercise:', error);
      throw error;
    }

    return mapHealthRowToExerciseRecord(data);
  },
};

import { supabase } from '../config/supabase';
import { isOrderSyncedFoodNutrition } from '../utils/mealUtils';

export interface FoodRecord {
  id: string;
  user_id: string;
  value: number;
  unit: string;
  notes?: string;
  recorded_at: string;
  created_at: string;
  updated_at: string;
  nutrition_data?: any;
}

export const foodService = {
  async getRecords(userId: string, startDate?: Date, endDate?: Date): Promise<FoodRecord[]> {
    let query = supabase
      .from('health_records')
      .select('*')
      .eq('user_id', userId)
      .eq('record_type', 'food');

    if (startDate) {
      query = query.gte('recorded_at', startDate.toISOString());
    }
    if (endDate) {
      const endDateTime = new Date(endDate.getTime());
      // 仅当结束时间为「当天 0 点」时扩展到 23:59:59，避免破坏已带具体时刻的区间（如北京日 bounds）
      if (
        endDateTime.getHours() === 0 &&
        endDateTime.getMinutes() === 0 &&
        endDateTime.getSeconds() === 0 &&
        endDateTime.getMilliseconds() === 0
      ) {
        endDateTime.setHours(23, 59, 59, 999);
      }
      query = query.lte('recorded_at', endDateTime.toISOString());
    }

    query = query.order('recorded_at', { ascending: false });

    const { data, error } = await query;

    if (error) throw error;

    return (data || []).map(r => ({
      id: r.id,
      user_id: r.user_id,
      value: r.value,
      unit: r.unit || 'g',
      notes: r.notes,
      recorded_at: r.recorded_at,
      created_at: r.created_at,
      updated_at: r.updated_at,
      nutrition_data: r.nutrition_data,
    }));
  },

  /** 获取今日已摄入的餐次（从 health_records 推导，用于全站同步） */
  async getTodayConsumedMealTypes(userId: string): Promise<Set<string>> {
    const today = new Date();
    today.setHours(0, 0, 0, 0);
    const endOfToday = new Date(today);
    endOfToday.setHours(23, 59, 59, 999);
    const records = await this.getRecords(userId, today, endOfToday);
    const mealTypeToKey: Record<string, string> = {
      早餐: 'breakfast',
      午餐: 'lunch',
      晚餐: 'dinner',
      加餐: 'snack',
      breakfast: 'breakfast',
      lunch: 'lunch',
      dinner: 'dinner',
      snack: 'snack',
    };
    const consumed = new Set<string>();
    records.forEach((r) => {
      const nd = r.nutrition_data;
      const mt = nd?.mealType;
      const key = mt != null ? mealTypeToKey[String(mt)] : undefined;
      const fromSync = isOrderSyncedFoodNutrition(nd);
      if (fromSync && key && ['breakfast', 'lunch', 'dinner'].includes(key)) {
        consumed.add(key);
      } else {
        consumed.add('snack');
      }
    });
    return consumed;
  },
};

import { supabase } from '../config/supabase';
import { OnboardingData } from '../contexts/OnboardingContext';
import { calculateHealthScores } from '../utils/healthAssessmentScoring';

export interface HealthAssessmentData {
  id?: string;
  user_id: string;
  assessment_date: string;
  diet_score: number;
  fitness_score: number;
  rest_score: number;
  psychology_score: number;
  exercise_score: number;
  overall_score: number;
  primary_improvement_area: string;
  questionnaire_data: OnboardingData;
}

export const healthAssessmentService = {
  /**
   * CRITICAL: Creates a NEW health assessment record (NEVER updates existing)
   * Each assessment is an independent snapshot at a specific point in time
   * - First-time onboarding: Creates initial assessment
   * - Reassessment: Creates NEW independent record (old records remain unchanged)
   *
   * @param data - The onboarding questionnaire data from current session
   * @param isReassessment - Optional flag to indicate this is a reassessment (for logging)
   * @returns Promise with new assessment data or error
   */
  async createAssessment(
    data: OnboardingData,
    isReassessment: boolean = false
  ): Promise<{ data: HealthAssessmentData | null; error: any }> {
    try {
      console.log('🔷 [healthAssessmentService] createAssessment called', {
        isReassessment,
        hasData: !!data,
        dataKeys: Object.keys(data || {})
      });

      const { data: { user } } = await supabase.auth.getUser();
      if (!user) {
        console.error('❌ [healthAssessmentService] No authenticated user');
        return { data: null, error: new Error('User not authenticated') };
      }

      console.log('👤 [healthAssessmentService] User:', user.id);

      // Validate required data fields
      if (!data.nickname || !data.age || !data.currentWeight || !data.height) {
        console.error('❌ [healthAssessmentService] Missing required fields:', {
          hasNickname: !!data.nickname,
          hasAge: !!data.age,
          hasCurrentWeight: !!data.currentWeight,
          hasHeight: !!data.height
        });
        return {
          data: null,
          error: new Error('Missing required assessment data')
        };
      }

      // Calculate scores from questionnaire data
      const scores = calculateHealthScores(data);
      console.log('📊 [healthAssessmentService] Calculated scores:', scores);

      // CRITICAL: Create immutable snapshot of questionnaire data
      // This prevents future modifications to the context from affecting this record
      const questionnaireSnapshot = JSON.parse(JSON.stringify(data));
      console.log('📸 [healthAssessmentService] Created immutable data snapshot');

      const assessmentData: Omit<HealthAssessmentData, 'id'> = {
        user_id: user.id,
        assessment_date: new Date().toISOString(),
        diet_score: scores.diet,
        fitness_score: scores.fitness,
        rest_score: scores.rest,
        psychology_score: scores.psychology,
        exercise_score: scores.exercise,
        overall_score: scores.overall,
        primary_improvement_area: scores.primaryImprovementArea,
        questionnaire_data: questionnaireSnapshot,
      };

      console.log('📤 [healthAssessmentService] Inserting NEW assessment record (NEVER updating)...');
      console.log('📝 [healthAssessmentService] Assessment type:', isReassessment ? 'REASSESSMENT' : 'FIRST_TIME');

      // CRITICAL: This is ALWAYS an INSERT, NEVER an UPDATE
      // Each assessment creates a completely independent record
      const { data: result, error } = await supabase
        .from('health_assessments')
        .insert(assessmentData)
        .select()
        .single();

      if (error) {
        console.error('❌ [healthAssessmentService] Insert failed:', error);
        return { data: null, error };
      }

      console.log('✅ [healthAssessmentService] NEW assessment record created successfully!');
      console.log('🆔 [healthAssessmentService] New Assessment ID:', result.id);
      console.log('📅 [healthAssessmentService] Assessment Date:', result.assessment_date);
      console.log('📊 [healthAssessmentService] Overall Score:', result.overall_score);

      return { data: result, error: null };
    } catch (error) {
      console.error('❌ [healthAssessmentService] FATAL: Error creating health assessment:', error);
      return { data: null, error };
    }
  },

  async getLatestAssessment(): Promise<{ data: HealthAssessmentData | null; error: any }> {
    try {
      const { data: { user } } = await supabase.auth.getUser();
      if (!user) {
        return { data: null, error: new Error('User not authenticated') };
      }

      const { data, error } = await supabase
        .from('health_assessments')
        .select('*')
        .eq('user_id', user.id)
        .order('assessment_date', { ascending: false })
        .limit(1)
        .maybeSingle();

      return { data, error };
    } catch (error) {
      console.error('Error fetching latest assessment:', error);
      return { data: null, error };
    }
  },

  async getAllAssessments(): Promise<{ data: HealthAssessmentData[] | null; error: any }> {
    try {
      const { data: { user } } = await supabase.auth.getUser();
      if (!user) {
        return { data: null, error: new Error('User not authenticated') };
      }

      const { data, error } = await supabase
        .from('health_assessments')
        .select('*')
        .eq('user_id', user.id)
        .order('assessment_date', { ascending: false });

      return { data, error };
    } catch (error) {
      console.error('Error fetching all assessments:', error);
      return { data: null, error };
    }
  },

  async getAssessmentById(id: string): Promise<{ data: HealthAssessmentData | null; error: any }> {
    try {
      const { data: { user } } = await supabase.auth.getUser();
      if (!user) {
