  async deleteAssessment(id: string): Promise<{ error: any }> {
    try {
      const { data: { user } } = await supabase.auth.getUser();
      if (!user) {
        return { error: new Error('User not authenticated') };
      }

      const { error } = await supabase
        .from('health_assessments')
        .delete()
        .eq('id', id)
        .eq('user_id', user.id);

