    "慢跑",
    "游泳",
    "骑车",
    "骑行",
    "跳绳",
    "瑜伽",
    "热量",
    "千卡",
    "卡路里",
    "大卡",
    "摄入",
    "补剂",
    "维生素",
    "蛋白粉",
    "钙片",
    "鱼油",
    "益生菌",
    "胶囊",
    "腰围",
    "围度",
    "胸围",
    "臀围",
    "上臂",
    "大腿",
    "小腿",
    "心情",
    "情绪",
    "感觉",
    "压力",
    "焦虑",
    "开心",
    "难过",
    "健康档案",
    "档案",
    "记录",
    "早餐",
    "午餐",
    "晚餐",
    "加餐",
    "餐食",
    "吃饭",
    "吃了",
    "配送",
    "送餐",
    "外卖",
    "送到",
    "收货",
  ];
  if (hints.some((h) => text.includes(h))) return true;
  if (/(?:早|午|晚)餐|加餐/.test(text)) return true;
  if (/(?:配送|送餐|送到|外卖|收货)/.test(text)) return true;
  if (/(?:喝|饮).{0,8}?(?:多少|几多)|多少.{0,8}?(?:毫升|ml|ML|水)/i.test(text)) return true;
  return false;
}

/** 明显是在报数/录入（仍应生成待确认卡片） */
function hasExplicitMetricRecordingIntent(text: string): boolean {
  const t = text.replace(/\s/g, "");
  if (
    /\d+\.?\d*\s*(?:ml|毫升|ML|L|l|升|千卡|kcal|大卡|步|分钟|min|小时|kg|公斤|千克|斤|克|g|mmol|毫摩尔)/i.test(
      t,
    )
  ) {
    return true;
  }
  if (/\d{3,}\s*步/.test(t)) return true;
  if (/(?:吃了|喝了|走了|跑了|睡了)\s*\d/.test(t)) return true;
  if (/(?:体重|血糖|血压|腰围|胸围|臀围|睡眠)[\s：:]*\d+\.?\d*/.test(text)) return true;
  if (/\d+\s*(?:个|碗|杯|份|块|片|条|根|只|袋|包)/.test(text) && /(?:吃|喝|包子|米饭|面条|粥|苹果|香蕉|鸡蛋)/.test(text)) {
    return true;
  }
  return false;
}

/**
 * 健康/档案类咨询问句：不生成 quickEntry 待确认卡片，交给对话与快照回答。
 * （与 isFoodQuestionOnly / isDeliveryLogisticsQuestion 叠加；显式报数时仍走录入。）
 */
function isHealthArchiveQueryQuestion(text: string): boolean {
  if (!looksLikeQuestion(text)) return false;
  if (!mentionsHealthArchiveTopic(text)) return false;
  if (hasExplicitMetricRecordingIntent(text)) return false;
  return true;
}

/**
 * Detection patterns for health metrics（关键词/正则见 config/healthMetricDetectionConfig.ts）
 */
const detectionPatterns: DetectionPattern[] = [
    // 补剂相关
    {
      ...supplementDetection,
      metricType: 'supplement',
      extractValue: (match) => {
        let supplementName = '补剂';
        let dosage = '1粒';

        if (match[1] && match[2]) {
          if (!isNaN(parseFloat(match[1]))) {
            dosage = `${match[1]}粒`;
            supplementName = match[2];
          } else {
            supplementName = match[1];
            dosage = `${match[2]}粒`;
          }
        } else if (match[1]) {
          supplementName = match[1];
        }

        return {
          metricType: 'supplement',
          value: 1,
          supplementName,
          dosage,
          unit: '次',
          date: new Date()
        };
      }
    },
    // 食物相关
    {
      ...foodDetection,
      metricType: 'food',
      extractValue: (match, text) => {
        const getMealType = () => {
          // 优先：用户明确说的餐次，避免时间推断覆盖
          if (text.includes('加餐')) return '加餐';
          if (text.includes('早餐')) return '早餐';
          if (text.includes('午餐')) return '午餐';
          if (text.includes('晚餐')) return '晚餐';
          const hour = new Date().getHours();
          if (hour >= 6 && hour < 11.5) return '早餐';
          if (hour >= 11.5 && hour < 18) return '午餐';
          if (hour >= 18 && hour <= 22) return '晚餐';
          return '加餐';
        };

        let foodName = '';
        let quantity = 1;
        let unit = '份';

        // Detect weight unit from original text
        const weightUnitMatch = text.match(/(\d+\.?\d*)(斤|两|克|千克|kg|公斤|g)/);

        if (weightUnitMatch) {
          // This is a weight-based pattern (e.g., "吃了3斤牛肉")
          quantity = parseFloat(weightUnitMatch[1]);
          unit = weightUnitMatch[2];

          // Extract food name after the unit - improved to capture complete food names
          const foodMatch = text.match(/(?:斤|两|克|千克|kg|公斤|g)([^，。\s,]+)/);
          if (foodMatch && foodMatch[1]) {
            foodName = foodMatch[1].trim();
          } else if (match[2]) {
            foodName = match[2].trim();
          }

          // Remove any trailing punctuation or special chars
          foodName = foodName.replace(/[，。、！？;；:：]+$/g, '');
        } else {
          // Standard pattern matching (e.g., "吃了3个包子")
          if (match[1] && match[2]) {
            if (!isNaN(parseFloat(match[1]))) {
              quantity = parseFloat(match[1]);
              foodName = match[2].trim();

              // Detect and extract unit from text
              const unitMatch = text.match(/\d+(?:个|碗|盘|杯|份|块|条|根|片|只|袋|包)/);
              if (unitMatch) {
                const detectedUnit = unitMatch[0].replace(/\d+/, '');
                unit = detectedUnit;
              } else {
                unit = '个';
              }
            } else if (
              match[2] &&
              /^(吃(?:了|过)?|喝(?:了|过)?)$/.test(String(match[1] ?? "").trim())
            ) {
              // Pattern 3：餐次 + 吃/喝 + 食物名（match[1] 为动词，match[2] 为食物）
              foodName = String(match[2]).trim();
              quantity = 1;
              unit = "份";
            } else {
              foodName = match[1].trim();
              quantity = 1;
            }
          } else if (match[1]) {
            foodName = match[1].trim();
            quantity = 1;
          }

          // Clean up food name: remove leading measure words only if the food name
          // is exactly the measure word (e.g., if user just says "个" as food name)
          // This prevents removing characters from actual food names like "包子" (steamed bun)
          const measureWords = ['个', '碗', '盘', '杯', '份', '块', '条', '根', '片', '只', '袋', '包'];
          // Only remove if food name is exactly a single measure word (not part of a food name)
          if (foodName.length === 1 && measureWords.includes(foodName)) {
            foodName = '';
          }

          // Remove any trailing punctuation or special chars
          foodName = foodName.replace(/[，。、！？;；:：]+$/g, '');
        }

        // Estimate calories based on common foods and units (per 100g or per piece)
        const calorieEstimates: { [key: string]: number } = {
          // 主食类 (per 100g)
          '包子': 220, '油条': 270, '米饭': 116, '白米饭': 116, '大米饭': 116,
          '面条': 138, '馒头': 221, '花卷': 200, '烙饼': 255, '炒饭': 180,
          '炒面': 160, '方便面': 470, '小米粥': 46, '粥': 46, '面包': 260,
          // 肉类 (per 100g)
          '牛肉': 125, '猪肉': 143, '鸡肉': 167, '鱼肉': 104, '鱼': 104,
          '羊肉': 203, '鸭肉': 240, '火腿': 330, '香肠': 508, '培根': 541, '虾': 93,
          // 蔬菜类 (per 100g)
          '白菜': 17, '菠菜': 24, '西兰花': 36, '胡萝卜': 39, '土豆': 81,
          '西红柿': 19, '黄瓜': 16, '茄子': 25, '青菜': 15, '蔬菜': 30,
          // 水果类 (per 100g)
          '苹果': 52, '香蕉': 89, '橙子': 48, '葡萄': 69, '西瓜': 30,
          '草莓': 32, '水果': 50,
          // 零食类 (per 100g)
          '薯片': 548, '饼干': 433, '蛋糕': 347, '巧克力': 589, '糖果': 400,
          // 其他常见 (per piece or per 100g)
          '饺子': 40, '蛋': 70, '鸡蛋': 144, '饼': 250
        };

        let estimatedCalories = 200; // Default

        // Calculate based on food name
        let baseCalorie = 200;
        for (const [food, cal] of Object.entries(calorieEstimates)) {
          if (foodName.includes(food)) {
            baseCalorie = cal;
            break;
          }
        }

        // Adjust for weight units
        if (unit === '斤') {
          estimatedCalories = baseCalorie * quantity; // per 100g, 1斤=500g, so multiply by quantity
        } else if (unit === '两') {
          estimatedCalories = baseCalorie * quantity * 0.1; // 1两=50g
        } else if (unit === 'g' || unit === '克') {
          estimatedCalories = (baseCalorie / 100) * quantity; // per 100g
        } else if (unit === 'kg' || unit === '千克' || unit === '公斤') {
          estimatedCalories = baseCalorie * quantity * 10; // 1kg=1000g
        } else {
          // For pieces/servings
          estimatedCalories = baseCalorie * quantity;
        }

        return {
          metricType: 'food',
          value: quantity,
          foodName: foodName || '食物',
          calories: Math.round(estimatedCalories),
          mealType: getMealType(),
          quantity: quantity,
          unit: unit,
          date: new Date()
        };
      }
    },

    // 喝水相关（包括饮品）
    {
      ...waterDetection,
      metricType: 'water',
      extractValue: (match, text) => {
        let value = parseFloat(match[1]);
        let drinkName = '';

        // 🔥 修复：扩展饮品识别，支持更多饮品类型
        if (text.includes('茶水') || text.includes('茶')) {
          drinkName = '茶水';
        } else if (text.includes('咖啡')) {
          drinkName = '咖啡';
        } else if (text.includes('奶茶')) {
          drinkName = '奶茶';
        } else if (text.includes('豆浆')) {
          drinkName = '豆浆';
        } else if (text.includes('牛奶')) {
          drinkName = '牛奶';
        } else if (text.includes('果汁')) {
          drinkName = '果汁';
        } else if (text.includes('饮料')) {
          drinkName = '饮料';
        }

        // Convert liters to ml（「毫升/ml」已是毫升，禁止把「毫升」里的「升」当升）
        const raw = match[0];
        if (raw.includes('毫升') || /ml/i.test(raw)) {
          // 已是 ml
        } else if (!raw.includes('毫') && (raw.includes('升') || /\d+\.?\d*\s*(?:L|l)(?:\s|$|水)/i.test(raw))) {
          value = value * 1000;
        }
        // If the number seems like cups (typically 1-10), convert to ml
        else if (value <= 20 && !raw.includes('ml') && !raw.includes('毫升')) {
          value = value * 250; // Assume 250ml per cup
        }

        return {
          metricType: 'water',
          value: value,
          unit: 'ml',
          notes: drinkName ? `喝了${drinkName}` : '',
          date: new Date()
        };
      }
    },

    // 运动相关
    {
      ...exerciseDetection,
      metricType: 'exercise',
      extractValue: (match, text) => {
        let exerciseName = '运动';
        let duration = 0;

        // 配速映射（分钟/公里）
        const paceMap: { [key: string]: number } = {
          '跑步': 6, '慢跑': 7, '跑': 6,
          '快走': 10, '走路': 12, '走': 12,
          '游泳': 20, '骑车': 4, '骑行': 4
        };

        // 先检测是否是距离单位（公里）
        const kmMatch = text.match(/(跑步|慢跑|跑|快走|走路|走|游泳|骑车|骑行)了?(\d+\.?\d*)(?:公里|km|千米)/i);

        if (kmMatch) {
          // 距离模式（公里）
          exerciseName = kmMatch[1];
          const distanceInKm = parseFloat(kmMatch[2]);
          const pace = paceMap[exerciseName] || 6;
          duration = Math.round(distanceInKm * pace);

          // 标准化运动名称
          if (exerciseName === '跑') exerciseName = '跑步';
          if (exerciseName === '走') exerciseName = '走路';
        } else {
          // 检测是否是距离单位（米）
          const meterMatch = text.match(/(跑步|慢跑|跑|快走|走路|走|游泳|骑车|骑行)了?(\d+\.?\d*)(?:米|m)(?!l)/i);

          if (meterMatch) {
            // 距离模式（米）
            exerciseName = meterMatch[1];
            const distanceInMeters = parseFloat(meterMatch[2]);
            const distanceInKm = distanceInMeters / 1000;
            const pace = paceMap[exerciseName] || 6;
            duration = Math.round(distanceInKm * pace);

            // 标准化运动名称
            if (exerciseName === '跑') exerciseName = '跑步';
            if (exerciseName === '走') exerciseName = '走路';
          } else {
            // 时间模式
            if (match[1] && match[2]) {
              if (!isNaN(parseFloat(match[1]))) {
                duration = parseFloat(match[1]);
                exerciseName = match[2];
              } else {
                exerciseName = match[1];
                duration = parseFloat(match[2]);
              }
            } else if (match[1]) {
              if (!isNaN(parseFloat(match[1]))) {
                duration = parseFloat(match[1]);
              } else {
                exerciseName = match[1];
                duration = 30; // Default duration
              }
            }
          }
        }

        // Estimate calories burned (per minute)
        const calorieRates: { [key: string]: number } = {
          // 有氧运动
          '跑步': 10, '慢跑': 8, '快走': 5, '走路': 4, '游泳': 11, '骑车': 7, '骑行': 7,
          '跳绳': 12, '爬楼梯': 9, '爬山': 8, '登山': 8,
          // 力量训练
          '俯卧撑': 8, '深蹲': 8, '举哑铃': 6, '哑铃': 6, '引体向上': 10, '平板支撑': 5,
          // 球类运动
          '篮球': 8, '足球': 9, '羽毛球': 7, '乒乓球': 5, '网球': 8, '排球': 6,
          // 其他运动
          '健身': 6, '瑜伽': 3, '普拉提': 4, '舞蹈': 5, '拳击': 10, '太极': 3, '广场舞': 4
        };

        let calorieRate = 6; // Default
        for (const [exercise, rate] of Object.entries(calorieRates)) {
          if (exerciseName.includes(exercise)) {
            calorieRate = rate;
            break;
          }
        }

        return {
          metricType: 'exercise',
          value: duration,
          exerciseName: exerciseName,
          duration: duration,
          calories: duration * calorieRate,
          unit: '分钟',
          exerciseType: 'cardio',
          date: new Date()
        };
      }
    },

    // 步数相关
    {
      ...stepsDetection,
      metricType: 'steps',
      extractValue: (match) => {
        return {
          metricType: 'steps',
          value: parseFloat(match[1]),
          unit: '步',
          date: new Date()
        };
      }
    },

    // 体重相关
    {
      ...weightDetection,
      metricType: 'weight',
      extractValue: (match) => {
        let value = parseFloat(match[1]);

        // Convert 斤 to kg if needed
        if (match[0].includes('斤')) {
          value = value / 2; // 1kg = 2斤
        }

        return {
          metricType: 'weight',
          value: value,
          unit: 'kg',
          date: new Date()
        };
      }
    },

    // 睡眠相关
    {
      ...sleepDetection,
      metricType: 'sleep',
      extractValue: (match) => {
        return {
          metricType: 'sleep',
          value: parseFloat(match[1]),
          unit: '小时',
          date: new Date()
        };
      }
    },

    // 血糖相关
    {
      ...bloodGlucoseDetection,
      metricType: 'blood_glucose',
      extractValue: (match) => {
        return {
          metricType: 'blood_glucose',
          value: parseFloat(match[1]),
          unit: 'mmol/L',
          date: new Date()
        };
      }
    },

    // 心情相关
    {
      ...emotionDetection,
      metricType: 'emotion',
      extractValue: (match, text) => {
        // 心情类型映射
        const emotionMap: { [key: string]: string } = {
          // 积极情绪 -> happy
          '开心': 'happy', '高兴': 'happy', '快乐': 'happy', '愉快': 'happy', '满足': 'happy', '幸福': 'happy', '喜悦': 'happy',
          // 兴奋 -> excited
          '兴奋': 'excited', '激动': 'excited', '振奋': 'excited', '充满活力': 'excited',
          // 消极情绪 -> sad
          '难过': 'sad', '伤心': 'sad', '不开心': 'sad', '沮丧': 'sad', '失落': 'sad', '悲伤': 'sad', '郁闷': 'sad',
          // 生气 -> angry
          '生气': 'angry', '愤怒': 'angry', '烦躁': 'angry', '气愤': 'angry', '恼火': 'angry', '暴躁': 'angry', '愤慨': 'angry',
          // 担心 -> worried
          '担心': 'worried', '焦虑': 'worried', '紧张': 'worried', '不安': 'worried', '忧虑': 'worried', '恐惧': 'worried', '害怕': 'worried',
          // 疲惫 -> tired
          '累': 'tired', '疲惫': 'tired', '困': 'tired', '乏力': 'tired', '疲劳': 'tired', '疲倦': 'tired', '筋疲力尽': 'tired',
          // 平静 -> neutral
          '平静': 'neutral', '放松': 'neutral'
        };

        // 提取心情关键词
        let emotionType = 'neutral';
        const matchedText = match[1] || text;
        const searchText = matchedText || text;

        // 🔥 修复：优先检查否定词（如"不开心"），避免被错误识别为"开心"
        if (text.includes('不开心') || text.includes('不 开心') || matchedText === '不开心') {
          emotionType = 'sad';
        } else {
          // 🔥 修复：按长度降序排序，优先匹配更长的词（如"心情不好"优先于"心情"）
          const sortedEmotions = Object.entries(emotionMap).sort((a, b) => b[0].length - a[0].length);

          for (const [chinese, english] of sortedEmotions) {
            // 检查文本中是否包含该情绪词
            if (searchText.includes(chinese)) {
              emotionType = english;
              break;
            }
          }
        }

        // 根据情绪类型设置强度
        const intensityMap: { [key: string]: number } = {
          'happy': 0.8,
          'excited': 0.9,
          'sad': 0.7,
          'angry': 0.9,
          'worried': 0.6,
          'tired': 0.5,
          'neutral': 0.5
        };

        return {
          metricType: 'emotion',
          value: 1,
          emotionType: emotionType,
          intensity: intensityMap[emotionType] || 0.5,
          unit: '次',
          date: new Date()
        };
      }
    },
    // 围度相关
    {
      ...measurementsDetection,
      metricType: 'measurements',
      extractValue: (match, text) => {
        const measurements: {
          chest?: number;
          waist?: number;
          upperArm?: number;
          hips?: number;
          thigh?: number;
          calf?: number;
        } = {};

        // 提取所有匹配的围度值
        // Pattern 1-6: 单个围度
        if (match[1] && match[2]) {
          const type = match[1];
          const value = parseFloat(match[2]);

          if (type.includes('胸')) {
            measurements.chest = value;
          } else if (type.includes('腰')) {
            measurements.waist = value;
          } else if (type.includes('臀')) {
            measurements.hips = value;
          } else if (type.includes('上臂') || type.includes('臂围')) {
            measurements.upperArm = value;
          } else if (type.includes('大腿')) {
            measurements.thigh = value;
          } else if (type.includes('小腿')) {
            measurements.calf = value;
          }
        }

        // Pattern 7: 两个围度
        if (match[1] && match[2] && match[3] && match[4]) {
          const type1 = match[1];
          const value1 = parseFloat(match[2]);
          const type2 = match[3];
          const value2 = parseFloat(match[4]);

          if (type1.includes('胸')) measurements.chest = value1;
          if (type1.includes('腰')) measurements.waist = value1;
          if (type1.includes('臀')) measurements.hips = value1;

          if (type2.includes('胸')) measurements.chest = value2;
          if (type2.includes('腰')) measurements.waist = value2;
          if (type2.includes('臀')) measurements.hips = value2;
        }

        // Pattern 8: 六个围度一起
        if (match.length >= 11) {
          measurements.chest = parseFloat(match[2]);
          measurements.waist = parseFloat(match[4]);
          measurements.hips = parseFloat(match[6]);
          measurements.upperArm = parseFloat(match[8]);
          measurements.thigh = parseFloat(match[10]);
          measurements.calf = parseFloat(match[12]);
        }

        // Pattern 9: 简写格式
        if (match[1] && match[2] && match[3] && !match[4]) {
          measurements.chest = parseFloat(match[1]);
          measurements.waist = parseFloat(match[2]);
          measurements.hips = parseFloat(match[3]);
        }

        // 如果从文本中还能提取其他围度值，也提取出来
        const allPatterns = [
          { pattern: /(胸围|胸).*?(\d+\.?\d*)/, key: 'chest' },
          { pattern: /(腰围|腰).*?(\d+\.?\d*)/, key: 'waist' },
          { pattern: /(臀围|臀).*?(\d+\.?\d*)/, key: 'hips' },
          { pattern: /(上臂围|上臂|臂围).*?(\d+\.?\d*)/, key: 'upperArm' },
          { pattern: /(大腿围|大腿).*?(\d+\.?\d*)/, key: 'thigh' },
          { pattern: /(小腿围|小腿).*?(\d+\.?\d*)/, key: 'calf' }
        ];

        for (const { pattern, key } of allPatterns) {
          const m = text.match(pattern);
          if (m && m[2]) {
            const value = parseFloat(m[2]);
            if (!measurements[key as keyof typeof measurements] || measurements[key as keyof typeof measurements] !== value) {
              (measurements as any)[key] = value;
            }
          }
        }

        // 计算主要值（用于显示）
        const values = Object.values(measurements).filter(v => v !== undefined) as number[];
        const primaryValue = values.length > 0 ? values[0] : 0;

        return {
          metricType: 'measurements',
          value: primaryValue,
          unit: 'cm',
          measurements: measurements,
          measurementType: 'body',
          date: new Date()
        };
      }
    }
];

/**
 * Validate extracted data
 */
/**
 * 同一条用户消息解析出多指标时，列表/卡片展示顺序（数值类优先于情绪等）
 */
const METRIC_DISPLAY_PRIORITY: Record<string, number> = {
  blood_glucose: 100,
  water: 95,
  weight: 88,
  sleep: 82,
  food: 75,
  exercise: 70,
  steps: 65,
  supplement: 60,
  measurements: 55,
  emotion: 45,
};

export function sortDetectionResultsByPriority(results: DetectionResult[]): DetectionResult[] {
  return [...results].sort((a, b) => {
    const ta = a.data?.metricType ?? '';
    const tb = b.data?.metricType ?? '';
    return (METRIC_DISPLAY_PRIORITY[tb] ?? 0) - (METRIC_DISPLAY_PRIORITY[ta] ?? 0);
  });
}

function isValidData(data: Partial<QuickEntryData>): boolean {
  if (!data.metricType || data.value === undefined || data.value === null) {
    return false;
  }

  // Check reasonable value ranges
  switch (data.metricType) {
    case 'food':
      return data.calories !== undefined && data.calories > 0 && data.calories < 5000;
    case 'water':
      return data.value > 0 && data.value <= 10000; // Max 10L
    case 'exercise':
      return data.duration !== undefined && data.duration > 0 && data.duration <= 300; // Max 5 hours
    case 'steps':
      return data.value >= 0 && data.value <= 100000;
    case 'weight':
      return data.value > 20 && data.value < 300; // Reasonable weight range
    case 'sleep':
      return data.value > 0 && data.value <= 24;
    case 'blood_glucose':
      return data.value > 0 && data.value <= 30;
    case 'emotion':
      return data.emotionType !== undefined && ['happy', 'sad', 'neutral', 'excited', 'tired', 'worried', 'angry'].includes(data.emotionType);
    case 'measurements':
      return data.measurements !== undefined && Object.keys(data.measurements).length > 0;
    default:
      return true;
  }
}

export const healthMetricDetectionService = {
  /**
   * Detect health metrics from text message
   */
  detectMetrics(text: string): DetectionResult {
    if (!text || text.trim().length === 0) {
      return { detected: false, confidence: 0 };
    }

    // 第一步：将中文数字转换为阿拉伯数字
    const convertedText = replaceChineseNumbers(text);

    console.log('健康指标检测 - 原文本:', text);
    console.log('健康指标检测 - 转换后:', convertedText);

    // Check each pattern
    for (const pattern of detectionPatterns) {
      if (pattern.metricType === "food" && isFoodQuestionOnly(text)) {
        continue;
      }
      if (pattern.metricType === "food" && isDeliveryLogisticsQuestion(text)) {
        continue;
      }
      if (isHealthArchiveQueryQuestion(text)) {
        continue;
      }

      // First check if any keywords are present (使用原始文本检查关键词)
      const hasKeyword = pattern.keywords.some(keyword => text.includes(keyword));

      if (hasKeyword) {
        // Try each regex pattern (使用转换后的文本进行匹配)
        for (let pi = 0; pi < pattern.patterns.length; pi++) {
          const regex = pattern.patterns[pi];
          const match = convertedText.match(regex);

          if (match) {
            console.log('匹配成功 - 类型:', pattern.metricType, '匹配结果:', match);
            try {
              const extractedData = pattern.extractValue(match, convertedText);

              // Validate extracted data
              if (isValidData(extractedData)) {
                console.log('数据验证通过:', extractedData);
                return {
                  detected: true,
                  data: extractedData as QuickEntryData,
                  confidence: confidenceScoreForTier(pattern.patternConfidenceTiers?.[pi]),
                };
              } else {
                console.log('数据验证失败:', extractedData);
              }
            } catch (error) {
              console.error('Error extracting metric data:', error);
            }
          }
        }
      }
    }

    console.log('健康指标检测 - 未检测到任何指标');
    return { detected: false, confidence: 0 };
  },

  /**
   * 将包含多种指标类型的文本拆分为独立片段（如 "我吃两个包子和500毫升的水" → ["我吃两个包子", "500毫升的水"]）
   * 仅在 "和/还有/以及/，" 后跟 数字+单位（毫升/小时/分钟等）时拆分，避免误拆 "鱼和薯条"
   */
  _splitByConjunctionAndNumericUnit(text: string): string[] {
    const segments: string[] = [];
    const splitPattern = /(?:和|还有|以及|[,，、])\s*((?:\d+\.?\d*)\s*(?:毫升|ml|ML|小时|分钟|步|kg|公斤|千克|斤|克|g)(?:\s*的?\s*水)?)/gi;
    let lastEnd = 0;
    let match;

    while ((match = splitPattern.exec(text)) !== null) {
      const beforePart = text.slice(lastEnd, match.index).trim();
      const afterPart = match[1].trim();
      if (beforePart) segments.push(beforePart);
      if (afterPart) segments.push(afterPart);
      lastEnd = match.index + match[0].length;
    }
    const tail = text.slice(lastEnd).trim();
    if (tail) segments.push(tail);

    return segments.length > 0 ? segments : [text];
  },

  /** 叙事连接词后常为另一指标（运动/血糖/心情等），避免整句只生成一张饮食卡 */
  _splitNarrativeChunks(text: string): string[] {
    const parts = text
      .split(/\s*(?:然后|接着|之后|随后|并且|同时)\s*/)
      .map((s) => s.trim())
      .filter(Boolean);
    return parts.length > 0 ? parts : [text];
  },

  /** 在同一片段内再按血糖/血压、心情边界切开，便于分卡 */
  _splitGlucoseMoodTails(segments: string[]): string[] {
    const out: string[] = [];
    for (const seg of segments) {
      if (!seg) continue;
      const gParts = seg.split(/(?=血糖|血压)/).map((x) => x.trim()).filter(Boolean);
      for (const g of gParts) {
        const mParts = g.split(/(?=心情|情绪)/).map((x) => x.trim()).filter(Boolean);
        for (const m of mParts) {
          if (m) out.push(m);
        }
      }
    }
    return out.length > 0 ? out : segments;
  },

  _splitMultiMetricText(text: string): string[] {
    const narrative = this._splitNarrativeChunks(text);
    const merged: string[] = [];
    for (const n of narrative) {
      merged.push(...this._splitByConjunctionAndNumericUnit(n));
    }
    const refined = this._splitGlucoseMoodTails(merged.length > 0 ? merged : [text]);
    return refined.length > 0 ? refined : [text];
  },

  /**
   * Detect multiple metrics from text
   */
  detectMultipleMetrics(text: string): DetectionResult[] {
    const results: DetectionResult[] = [];
    const seenKeys = new Set<string>(); // 去重：同一类型+值只保留一个

    // 将中文数字转换为阿拉伯数字
    const convertedText = replaceChineseNumbers(text);

    // 🔥 拆分多指标文本：如 "我吃两个包子和500毫升的水" → 分别检测 "我吃两个包子" 和 "500毫升的水"
    const segments = this._splitMultiMetricText(convertedText);

    console.log('🔍 [HealthMetricDetection] 检测文本:', {
      原始文本: text,
      转换后: convertedText,
      拆分片段: segments
    });

    for (const segment of segments) {
      const segmentResults = this._detectMetricsInSegment(segment);
      for (const r of segmentResults) {
        if (r.detected && r.data) {
          const key = `${r.data.metricType}-${r.data.value}-${(r.data as any).foodName || (r.data as any).exerciseName || ''}`;
          if (!seenKeys.has(key)) {
            seenKeys.add(key);
            results.push(r);
          }
        }
      }
    }

    console.log(`📋 [HealthMetricDetection] 检测完成，共找到 ${results.length} 个指标`);
    return sortDetectionResultsByPriority(results);
  },

  /**
   * 在单个文本片段内检测指标（内部方法）
   */
  _detectMetricsInSegment(segmentText: string): DetectionResult[] {
    const results: DetectionResult[] = [];

    for (const pattern of detectionPatterns) {
      if (pattern.metricType === "food" && isFoodQuestionOnly(segmentText)) {
        console.log("🔍 [HealthMetricDetection] 跳过饮食检测：纯询问句（不生成待确认卡片）");
        continue;
      }
      if (pattern.metricType === "food" && isDeliveryLogisticsQuestion(segmentText)) {
        console.log("🔍 [HealthMetricDetection] 跳过饮食检测：配送/地址类咨询（不生成待确认卡片）");
        continue;
      }
      if (isHealthArchiveQueryQuestion(segmentText)) {
        console.log("🔍 [HealthMetricDetection] 跳过检测：健康档案类疑问句（不生成待确认卡片）");
        continue;
      }

      const hasKeyword = pattern.keywords.some(keyword => segmentText.includes(keyword));

      // 🔥 修复：添加调试日志
      if (hasKeyword) {
        console.log(`🔍 [HealthMetricDetection] 检测到关键词，类型: ${pattern.metricType}`);
      }

      if (hasKeyword) {
        for (let pi = 0; pi < pattern.patterns.length; pi++) {
          const regex = pattern.patterns[pi];
          const match = segmentText.match(regex);

          // 🔥 修复：添加调试日志
          if (match) {
            console.log(`✅ [HealthMetricDetection] 模式匹配成功:`, {
              类型: pattern.metricType,
              匹配结果: match,
              正则: regex.toString()
            });
          }

          if (match) {
            try {
              const extractedData = pattern.extractValue(match, segmentText);

              // 🔥 修复：添加调试日志
              console.log(`📊 [HealthMetricDetection] 提取的数据:`, extractedData);

              if (isValidData(extractedData)) {
                console.log(`✅ [HealthMetricDetection] 数据验证通过，添加到结果`);
                results.push({
                  detected: true,
                  data: extractedData as QuickEntryData,
                  confidence: confidenceScoreForTier(pattern.patternConfidenceTiers?.[pi]),
                });
                break; // Only take first match per pattern type
              } else {
                console.log(`❌ [HealthMetricDetection] 数据验证失败:`, extractedData);
              }
            } catch (error) {
              console.error('❌ [HealthMetricDetection] 提取数据时出错:', error);
            }
          }
        }
      }
    }

    return results;
  },

  /**
   * Get suggestions for ambiguous inputs
   */
  getSuggestions(text: string): string[] {
    const suggestions: string[] = [];

    // Check which keywords are mentioned
    const mentionedTypes = new Set<string>();

    for (const pattern of detectionPatterns) {
      if (pattern.keywords.some(keyword => text.includes(keyword))) {
        mentionedTypes.add(pattern.metricType);
      }
    }

    // Provide helpful suggestions
    if (mentionedTypes.has('food')) {
      suggestions.push('记得说明吃了什么和大概多少哦～');
    }
    if (mentionedTypes.has('exercise')) {
      suggestions.push('可以告诉我运动类型和时长～');
    }

    return suggestions;
  },
};

export interface LocalStorageItem<T> {
  data: T;
  timestamp: number;
  version: string; // 保留字段以兼容现有数据，但不再使用迁移功能
}

/**
 * 简化的localStorage服务
 * 符合架构规范：简单提示，非完整队列
 * React Query内置缓存即可，不需要复杂的版本迁移
 */

export const localStorageService = {
  /**
   * 保存数据到本地存储（简化版，无版本迁移）
   */
  save<T>(key: string, data: T): void {
    try {
      const item: LocalStorageItem<T> = {
        data,
        timestamp: Date.now(),
        version: '1.0.0' // 固定版本，不再支持迁移
      };
      localStorage.setItem(key, JSON.stringify(item));
    } catch (error) {
      console.error(`Error saving to localStorage: ${key}`, error);
    }
  },

  /**
   * 从本地存储获取数据（简化版，无版本迁移）
   */
  get<T>(key: string): T | null {
    try {
      const itemStr = localStorage.getItem(key);
      if (!itemStr) return null;

      const item: LocalStorageItem<T> = JSON.parse(itemStr);
      return item.data;
    } catch (error) {
      console.error(`Error getting from localStorage: ${key}`, error);
      return null;
    }
  },

  /**
   * 从本地存储获取数据，包括元数据
   */
  getItem<T>(key: string): LocalStorageItem<T> | null {
    try {
      const itemStr = localStorage.getItem(key);
      if (!itemStr) return null;

      return JSON.parse(itemStr) as LocalStorageItem<T>;
    } catch (error) {
      console.error(`Error getting item from localStorage: ${key}`, error);
      return null;
    }
  },

  /**
   * 从本地存储删除数据
   */
  remove(key: string): void {
    try {
      localStorage.removeItem(key);
    } catch (error) {
      console.error(`Error removing from localStorage: ${key}`, error);
    }
  },

  /**
   * 清空本地存储
   */
  clear(): void {
    try {
      localStorage.clear();
    } catch (error) {
      console.error('Error clearing localStorage', error);
    }
  },

  /**
   * 检查数据是否过期（简单实现）
   */
  isExpired(key: string, maxAge: number): boolean {
    try {
      const item = this.getItem(key);
      if (!item) return true;

      const now = Date.now();
      return (now - item.timestamp) > maxAge;
    } catch (error) {
      console.error(`Error checking expiration for ${key}`, error);
      return true;
    }
  },

  /**
   * 简单的离线操作队列（仅保存最近9条，符合规范要求）
   */
  saveForLater(key: string, data: any): void {
    try {
      const ops = JSON.parse(localStorage.getItem('offline_ops') || '[]');
      const updatedOps = [...ops.slice(-9), { key, data, timestamp: Date.now() }];
      localStorage.setItem('offline_ops', JSON.stringify(updatedOps));
    } catch (error) {
      console.error('Error saving offline operation:', error);
    }
  },

  /**
   * 获取离线操作队列
   */
  getOfflineOps(): Array<{ key: string; data: any; timestamp: number }> {
    try {
      return JSON.parse(localStorage.getItem('offline_ops') || '[]');
    } catch (error) {
      console.error('Error getting offline operations:', error);
      return [];
    }
  },

  /**
   * 清空离线操作队列
   */
  clearOfflineOps(): void {
    try {
      localStorage.removeItem('offline_ops');
    } catch (error) {
      console.error('Error clearing offline operations:', error);
    }
  },
};

import { supabase } from '../config/supabase';

export interface MeasurementRecord {
  id: string;
  user_id: string;
  value: number;
  unit: string;
  notes?: string;
  recorded_at: string;
  created_at: string;
  updated_at: string;
  measurement_data?: any;
}

/** 单次录入的六维围度（均可空，但至少应有一项有值，由调用方校验） */
export interface MeasurementBody {
  chest?: number | null;
  waist?: number | null;
  upperArm?: number | null;
  hips?: number | null;
  thigh?: number | null;
  calf?: number | null;
}

function toMeasurementData(body: MeasurementBody) {
  return {
    chest: body.chest ?? null,
    waist: body.waist ?? null,
    upperArm: body.upperArm ?? null,
    hips: body.hips ?? null,
    thigh: body.thigh ?? null,
    calf: body.calf ?? null,
  };
}

function primaryMetricValue(data: ReturnType<typeof toMeasurementData>): number {
  const v =
    data.waist ??
    data.chest ??
    data.hips ??
    data.upperArm ??
    data.thigh ??
    data.calf;
  return typeof v === 'number' && !Number.isNaN(v) ? v : 0;
}

export const measurementsService = {
  async getRecords(userId: string, startDate?: Date, endDate?: Date): Promise<MeasurementRecord[]> {
    let query = supabase
      .from('health_records')
      .select('*')
      .eq('user_id', userId)
      .eq('record_type', 'measurements');

    if (startDate) {
      query = query.gte('recorded_at', startDate.toISOString());
    }
    if (endDate) {
      const endDateTime = new Date(endDate);
      endDateTime.setHours(23, 59, 59, 999);
      query = query.lte('recorded_at', endDateTime.toISOString());
    }

    query = query.order('recorded_at', { ascending: false });

    const { data, error } = await query;

    if (error) throw error;

    return (data || []).map(r => ({
      id: r.id,
      user_id: r.user_id,
      value: r.value,
      unit: r.unit || 'cm',
      notes: r.notes,
      recorded_at: r.recorded_at,
      created_at: r.created_at,
      updated_at: r.updated_at,
      measurement_data: r.measurement_data,
    }));
  },

  async addRecord(
    userId: string,
    body: MeasurementBody,
    date: Date,
    notes?: string
  ): Promise<MeasurementRecord> {
    const measurement_data = toMeasurementData(body);
    const { data, error } = await supabase
      .from('health_records')
      .insert({
        user_id: userId,
        record_type: 'measurements',
        value: primaryMetricValue(measurement_data),
        unit: 'cm',
        notes: notes || '手动记录',
        measurement_data,
        recorded_at: date.toISOString(),
      })
      .select()
      .single();

    if (error) throw error;

    return {
      id: data.id,
      user_id: data.user_id,
      value: data.value,
      unit: data.unit || 'cm',
      notes: data.notes,
      recorded_at: data.recorded_at,
      created_at: data.created_at,
      updated_at: data.updated_at,
      measurement_data: data.measurement_data,
    };
  },

  async updateRecord(
    id: string,
    body: MeasurementBody,
    date: Date,
    notes?: string
  ): Promise<MeasurementRecord> {
    const measurement_data = toMeasurementData(body);
    const { data, error } = await supabase
      .from('health_records')
      .update({
        value: primaryMetricValue(measurement_data),
        measurement_data,
        notes,
        recorded_at: date.toISOString(),
        updated_at: new Date().toISOString(),
      })
      .eq('id', id)
      .select()
      .single();

    if (error) throw error;

    return {
      id: data.id,
      user_id: data.user_id,
      value: data.value,
      unit: data.unit || 'cm',
      notes: data.notes,
      recorded_at: data.recorded_at,
      created_at: data.created_at,
      updated_at: data.updated_at,
      measurement_data: data.measurement_data,
    };
  },

  async deleteRecord(id: string): Promise<void> {
    const { error } = await supabase.from('health_records').delete().eq('id', id);
    if (error) throw error;
  },
};

import { supabase } from '../config/supabase';
import { handleAuthError } from './errorHandler';
import { getBeijingDayBoundsForInstant } from '../utils/dateUtils';
import { insertHealthRecordWithChatMessageFallback } from '../utils/healthRecordsInsert';

interface NutritionData {
  calories: number;
  protein: number;
  carbs: number;
  fat: number;
  fiber: number;
}

interface DailyNutritionTotals {
  totalCalories: number;
  totalProtein: number;
  totalCarbs: number;
  totalFat: number;
  totalFiber: number;
  snackCalories: number;
  snackProtein: number;
  snackCarbs: number;
  snackFat: number;
}

export const nutritionSyncService = {
  /**
   * Calculate mock macronutrients based on calories
   * Uses standard ratios: 40% carbs, 30% protein, 30% fat
   */
  calculateMockMacros(calories: number): NutritionData {
    // Standard calorie-to-gram conversions:
    // 1g carbs = 4 calories
    // 1g protein = 4 calories
    // 1g fat = 9 calories

    const carbCalories = calories * 0.4;
    const proteinCalories = calories * 0.3;
    const fatCalories = calories * 0.3;

    return {
      calories,
      protein: Math.round(proteinCalories / 4),
      carbs: Math.round(carbCalories / 4),
      fat: Math.round(fatCalories / 9),
      fiber: Math.round(calories * 0.01) // Rough estimate: 1g fiber per 100 kcal
    };
  },

  /**
   * Get daily nutrition totals from health records
   */
  async getDailyNutritionTotals(date?: Date): Promise<DailyNutritionTotals> {
    try {
      const { data: { user } } = await supabase.auth.getUser();
      if (!user) {
        handleAuthError(new Error('User not authenticated'));
      }

      const targetDate = date || new Date();
      const { start: dayStart, end: dayEnd } = getBeijingDayBoundsForInstant(targetDate);

      // Fetch all food records for the day（按北京日历日与 dashboard / 日反馈一致）
      const { data: records, error } = await supabase
        .from('health_records')
        .select('*')
        .eq('user_id', user.id)
        .eq('record_type', 'food')
        .gte('recorded_at', dayStart.toISOString())
        .lte('recorded_at', dayEnd.toISOString());

      if (error) {
        console.error('Error fetching nutrition data:', error);
        return this.getEmptyTotals();
      }

      if (!records || records.length === 0) {
        return this.getEmptyTotals();
      }

      // Calculate totals
      let totalCalories = 0;
      let totalProtein = 0;
      let totalCarbs = 0;
      let totalFat = 0;
      let totalFiber = 0;
      let snackCalories = 0;
      let snackProtein = 0;
      let snackCarbs = 0;
      let snackFat = 0;

      console.log(`📊 [NutritionSync] Processing ${records.length} records for date:`, targetDate.toLocaleDateString());

      for (const record of records) {
        const nutritionData = record.nutrition_data;

        if (nutritionData) {
          const calories = nutritionData.calories || 0;
          const mealType = nutritionData.mealType || '加餐';
          const foodName = nutritionData.name || '未知食物';
          const isSnackSlot =
            mealType === '加餐' ||
            mealType === 'snack' ||
            String(mealType).toLowerCase() === 'snack';

          console.log(`  📝 Record: ${foodName} (${mealType}) - ${calories} kcal`, nutritionData);

          // Calculate macros (use stored values or calculate from calories)
          const macros = nutritionData.protein !== undefined
            ? {
                protein: nutritionData.protein,
                carbs: nutritionData.carbs,
                fat: nutritionData.fat,
                fiber: nutritionData.fiber || 0
              }
            : this.calculateMockMacros(calories);

          // Add to totals
          totalCalories += calories;
          totalProtein += macros.protein;
          totalCarbs += macros.carbs;
          totalFat += macros.fat;
          totalFiber += macros.fiber;

          // If it's a snack (加餐 / AI 统一写入的加餐)，加进加餐汇总
          if (isSnackSlot) {
            snackCalories += calories;
            snackProtein += macros.protein;
            snackCarbs += macros.carbs;
            snackFat += macros.fat;
          }
        }
      }

      const result = {
        totalCalories: Math.round(totalCalories),
        totalProtein: Math.round(totalProtein),
        totalCarbs: Math.round(totalCarbs),
        totalFat: Math.round(totalFat),
        totalFiber: Math.round(totalFiber),
        snackCalories: Math.round(snackCalories),
        snackProtein: Math.round(snackProtein),
        snackCarbs: Math.round(snackCarbs),
        snackFat: Math.round(snackFat)
      };

      console.log('✅ [NutritionSync] Totals calculated:', result);

      return result;
    } catch (error) {
      console.error('Error calculating daily nutrition totals:', error);
      return this.getEmptyTotals();
    }
  },

  /**
   * Save food entry with calculated macros
   * @param timeLabel 加餐场景展示标签（中午/晚上），用于替代「午餐」「晚餐」的展示
   * @param chatMessageId 可选，用于跨表稳定关联
   * @param opts.syncId 订单/排期「完成摄入」等与定制食谱同步同属官方餐食，写入后与营养详情、日反馈早午晚行一致；手动+、AI 勿传
   */
  async saveFoodEntry(
    foodName: string,
    calories: number,
    mealType: string,
    quantity: number = 1,
    date?: Date,
    source?: 'ai' | 'manual',
    timeLabel?: string,
    chatMessageId?: string,
    opts?: { syncId?: string }
  ): Promise<void> {
    try {
      const { data: { user } } = await supabase.auth.getUser();
      if (!user) {
        handleAuthError(new Error('User not authenticated'));
      }

      // calories is already the total calories (calculated as baseCalorie * quantity in healthMetricDetectionService)
      // So we don't need to multiply by quantity again
      const totalCalories = calories;

      // Calculate macros
      const macros = this.calculateMockMacros(totalCalories);

      const nutritionData: Record<string, any> = {
        name: foodName,
        calories: totalCalories,
        mealType: mealType,
        protein: macros.protein,
        carbs: macros.carbs,
        fat: macros.fat,
        fiber: macros.fiber,
        quantity: quantity,
        source: source || 'manual'
      };
      if (timeLabel) nutritionData.timeLabel = timeLabel;
      if (opts?.syncId) nutritionData.syncId = opts.syncId;

      const insertRow: Record<string, unknown> = {
        user_id: user.id,
        record_type: 'food',
        value: quantity,
        unit: '份',
        nutrition_data: nutritionData,
        recorded_at: date || new Date(),
      };
      if (chatMessageId) insertRow.chat_message_id = chatMessageId;

      const { error } = await insertHealthRecordWithChatMessageFallback(insertRow);
      if (error) {
        throw error;
      }
    } catch (error) {
      console.error('Error saving food entry:', error);
      throw error;
    }
  },

  /**
   * Get empty totals object
   */
  getEmptyTotals(): DailyNutritionTotals {
    return {
      totalCalories: 0,
      totalProtein: 0,
      totalCarbs: 0,
      totalFat: 0,
      totalFiber: 0,
      snackCalories: 0,
      snackProtein: 0,
      snackCarbs: 0,
      snackFat: 0
    };
  },

  /**
   * Get nutrition goals based on user profile
   */
  async getNutritionGoals(): Promise<{ protein: number; carbs: number; fat: number }> {
    try {
      const { data: { user } } = await supabase.auth.getUser();
      if (!user) {
        handleAuthError(new Error('User not authenticated'));
      }

      const { data: profile, error } = await supabase
        .from('user_profiles')
        .select('weight, height, gender, age, fitness_goal, tdee')
        .eq('user_id', user.id)
        .single();

      if (error || !profile) {
        // Return default goals
        return {
          protein: 120,
          carbs: 178,
          fat: 109
        };
      }

      // Calculate goals based on TDEE or use defaults
      const tdee = profile.tdee || 2000;

      // Standard distribution: 40% carbs, 30% protein, 30% fat
      return {
        protein: Math.round((tdee * 0.3) / 4), // 1g protein = 4 kcal
        carbs: Math.round((tdee * 0.4) / 4),   // 1g carbs = 4 kcal
        fat: Math.round((tdee * 0.3) / 9)      // 1g fat = 9 kcal
      };
    } catch (error) {
      console.error('Error getting nutrition goals:', error);
      return {
        protein: 120,
        carbs: 178,
        fat: 109
      };
    }
  }
};

// DistanceCalculator工具类 - 处理地址距离计算和配送费用计算

// 位置坐标接口
export interface Location {
  name: string;
  lat: number;
  lng: number;
}

// 配送范围信息接口
export interface DeliveryRangeInfo {
  inRange: boolean;
  fee: number;
  tier: string;
  message: string;
}

// 配送范围层级配置
interface DeliveryTier {
  maxDistance: number;
  fee: number;
  tierName: string;
  message: string;
}

export class DistanceCalculator {
  // 默认配送中心位置 - 双井
  public static DEFAULT_CENTER_LOCATION: Location = {
    name: "双井",
    lat: 39.9081,
    lng: 116.4528
  };

  // 配送范围层级配置
  private static DELIVERY_TIERS: DeliveryTier[] = [
    { maxDistance: 5, fee: 0, tierName: "核心区域", message: "免配送费" },
    { maxDistance: 10, fee: 5, tierName: "标准区域", message: "配送费¥5" },
    { maxDistance: 20, fee: 15, tierName: "扩展区域", message: "配送费¥15" }
  ];

  // 最大配送距离（公里）
  public static MAX_DELIVERY_DISTANCE = 20;

  /**
   * 计算地址与中心位置的距离（公里）
   * 使用简化的距离计算模型，基于地址文本中的区域信息进行估算
   * 注意：实际项目中可替换为真实的地图API计算
   */
  public static calculateDistance(address: string, centerLocation: Location = this.DEFAULT_CENTER_LOCATION): number {
    // 模拟距离计算逻辑
    // 实际项目中应使用地图API进行真实距离计算
    const areaKeywords: Record<string, number> = {
      "朝阳区": 3,
      "海淀区": 8,
      "东城区": 5,
      "西城区": 6,
      "丰台区": 7,
      "通州区": 12,
      "昌平区": 15,
      "大兴区": 18,
      "顺义区": 16,
      "房山区": 22,
      "北京": 10 // 默认北京区域距离
    };

    // 查找地址中的区域关键词
    for (const [keyword, distance] of Object.entries(areaKeywords)) {
      if (address.includes(keyword)) {
        return distance;
      }
    }

    // 对于非北京地区，返回超出范围的距离
    if (!address.includes("北京")) {
      return this.MAX_DELIVERY_DISTANCE + 1;
    }

    // 默认距离
    return 10;
  }

  /**
   * 计算配送费用
   * @param distance 距离（公里）
   * @returns 配送费用
   */
  public static calculateDeliveryFee(distance: number): number {
    // 超出最大配送距离，返回高额配送费或提示不可配送
    if (distance > this.MAX_DELIVERY_DISTANCE) {
      return 999; // 表示超出范围
    }

    // 查找对应的配送层级
    for (const tier of this.DELIVERY_TIERS) {
      if (distance <= tier.maxDistance) {
        return tier.fee;
      }
    }

    // 默认返回最高配送费
    return this.DELIVERY_TIERS[this.DELIVERY_TIERS.length - 1].fee;
  }

  /**
   * 检查是否在配送范围内
   * @param distance 距离（公里）
   * @returns 是否在配送范围内
   */
  public static isInDeliveryRange(distance: number): boolean {
    return distance <= this.MAX_DELIVERY_DISTANCE;
  }

  /**
   * 获取配送范围信息
   * @param distance 距离（公里）
   * @returns 配送范围详细信息
   */
  public static getDeliveryRangeInfo(distance: number): DeliveryRangeInfo {
    // 超出配送范围
    if (distance > this.MAX_DELIVERY_DISTANCE) {
      return {
        inRange: false,
        fee: 999,
        tier: "超出范围",
        message: "超出配送范围，暂不支持配送"
      };
    }

    // 查找对应的配送层级
    for (const tier of this.DELIVERY_TIERS) {
      if (distance <= tier.maxDistance) {
        return {
          inRange: true,
          fee: tier.fee,
          tier: tier.tierName,
          message: tier.message
        };
      }
    }

    // 默认返回最高层级信息
    const lastTier = this.DELIVERY_TIERS[this.DELIVERY_TIERS.length - 1];
    return {
      inRange: true,
      fee: lastTier.fee,
      tier: lastTier.tierName,
      message: lastTier.message
    };
  }

  /**
   * 验证地址区域是否在支持范围内
   * @param address 地址字符串
   * @param allowedRegions 允许的区域列表
   * @returns 是否在支持区域内
   */
  public static validateAddressRegion(address: string, allowedRegions: string[] = ['北京市']): boolean {
    // 转换为小写进行比较
    const lowerAddress = address.toLowerCase();

    // 检查是否包含任一允许的区域
    return allowedRegions.some(region => 
      lowerAddress.includes(region.toLowerCase())
    );
  }

  /**
   * 获取地址是否可配送的详细信息
   * @param address 地址字符串
   * @param centerLocation 配送中心位置
   * @param allowedRegions 允许的区域列表
   * @returns 配送可行性信息
   */
  public static getAddressDeliveryInfo(
    address: string,
    centerLocation: Location = this.DEFAULT_CENTER_LOCATION,
    allowedRegions: string[] = ['北京市']
  ): {
    canDeliver: boolean;
    regionValid: boolean;
    distanceValid: boolean;
    distance?: number;
    fee?: number;
    message: string;
  } {
    // 首先检查区域是否有效
    const regionValid = this.validateAddressRegion(address, allowedRegions);

    if (!regionValid) {
      return {
        canDeliver: false,
        regionValid: false,
        distanceValid: false,
        message: `不支持${allowedRegions.join('/')}以外区域的配送`
      };
    }

    // 计算距离
    const distance = this.calculateDistance(address, centerLocation);
    const rangeInfo = this.getDeliveryRangeInfo(distance);

    return {
      canDeliver: rangeInfo.inRange,
      regionValid: true,
      distanceValid: rangeInfo.inRange,
      distance,
      fee: rangeInfo.fee,
      message: rangeInfo.message
    };
  }
}

